# The sqlite_version() and sqlite_source_id() functions return values from the library.
# These are set by SQLITE_VERSION, SQLITE_VERSION_NUMBER, and SQLITE_SOURCE_ID macros
# in sqlite3.h.
# 
# If I use system libsqlite3 (3.37.2), these will return 3.37.2.
# 
# I could CREATE FUNCTION version() ... in SQLite to override? No.
# 
# The only way to make sqlite_version() return "3.54.0" is to:
# 1. Use a library compiled with those version strings
# 2. Override via an application-defined function
#
# For option 2: SQLite allows you to override built-in functions!
# sqlite3_create_function() can override existing functions.
# I can override sqlite_version(), sqlite_source_id(), etc.
#
# Let me test this approach:
cat > /tmp/test_version.c << 'EOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Declare the minimal SQLite API we need
typedef struct sqlite3 sqlite3;
typedef struct sqlite3_stmt sqlite3_stmt;
typedef struct sqlite3_context sqlite3_context;
typedef struct sqlite3_value sqlite3_value;

typedef void (*sqlite3_destructor_type)(void*);
#define SQLITE_TRANSIENT ((sqlite3_destructor_type)-1)

// Minimal declarations
int sqlite3_open(const char *filename, sqlite3 **ppDb);
int sqlite3_close(sqlite3*);
int sqlite3_exec(sqlite3*, const char *sql, int (*callback)(void*,int,char**,char**), void*, char **errmsg);
void sqlite3_free(void*);
const char *sqlite3_version;
const char *sqlite3_libversion(void);
const char *sqlite3_sourceid(void);
int sqlite3_libversion_number(void);

void sqlite3_result_text(sqlite3_context *ctx, const char *z, int n, sqlite3_destructor_type xDel);
int sqlite3_create_function(sqlite3*, const char *zFunctionName, int nArg, int eTextRep, void *pApp,
  void (*xFunc)(sqlite3_context*,int,sqlite3_value**),
  void (*xStep)(sqlite3_context*,int,sqlite3_value**),
  void (*xFinal)(sqlite3_context*));
#define SQLITE_UTF8 1

void my_version_func(sqlite3_context *ctx, int argc, sqlite3_value **argv) {
    sqlite3_result_text(ctx, "3.54.0", -1, SQLITE_TRANSIENT);
}

void my_sourceid_func(sqlite3_context *ctx, int argc, sqlite3_value **argv) {
    sqlite3_result_text(ctx, "2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b", -1, SQLITE_TRANSIENT);
}

int main() {
    sqlite3 *db;
    char *errmsg = NULL;

    sqlite3_open(":memory:", &db);

    // Override version functions
    sqlite3_create_function(db, "sqlite_version", 0, SQLITE_UTF8, NULL, my_version_func, NULL, NULL);
    sqlite3_create_function(db, "sqlite_source_id", 0, SQLITE_UTF8, NULL, my_sourceid_func, NULL, NULL);

    // Test
    int callback(void *notused, int argc, char **argv, char **colname) {
        for (int i = 0; i < argc; i++) printf("%s\n", argv[i] ? argv[i] : "NULL");
        return 0;
    }

    sqlite3_exec(db, "SELECT sqlite_version(), sqlite_source_id();", callback, NULL, &errmsg);

    sqlite3_close(db);
    return 0;
}
EOF

gcc -o /tmp/test_version /tmp/test_version.c -lsqlite3 2>&1
/tmp/test_version 2>&1

