/*
** Interpret escape sequences in a string
*/
static char *interpretEscapes(const char *z) {
  static char buf[200];
  int i = 0;
  int j = 0;
  while (z[i] && j < 190) {
    if (z[i] == '\\' && z[i+1]) {
      i++;
      switch(z[i]) {
        case 'n': buf[j++] = '\n'; break;
        case 't': buf[j++] = '\t'; break;
        case 'r': buf[j++] = '\r'; break;
        case '\\': buf[j++] = '\\'; break;
        default: buf[j++] = '\\'; buf[j++] = z[i]; break;
      }
    } else {
      buf[j++] = z[i];
    }
    i++;
  }
  buf[j] = 0;
  return buf;
}

/*
** Get current time in microseconds
*/
static sqlite3_int64 timeOfDay(void){
  struct timeval tv;
  gettimeofday(&tv, 0);
  return (sqlite3_int64)(tv.tv_sec*1000000 + tv.tv_usec);
}

static sqlite3_int64 HiResTimer(void){ return timeOfDay(); }

/*
** HTML escape a string
*/
static void htmlEncode(FILE *out, const char *z){
  while(z && *z){
    if(*z == '<' || *z == '>'){
      fputs("&lt;", out);
    } else if(*z == '&'){
      fputs("&amp;", out);
    } else if(*z == '"'){
      fputs("&quot;", out);
    } else {
      fputc(*z, out);
    }
    z++;
  }
}

/*
** CSV escape
*/
static void csvPrint(FILE *out, const char *z, const char *sep){
  int needQuote = 0;
  if(z==NULL){ fputs("", out); return; }
  if(strchr(z,'"') || strchr(z,'\n') || strchr(z,'\r') || strstr(z,sep))
    needQuote = 1;
  if(!needQuote){ fputs(z, out); return; }
  fputc('"', out);
  while(*z){
    if(*z=='"') fputc('"', out);
    fputc(*z, out);
    z++;
  }
  fputc('"', out);
}

/*
** Read a line from stdin, returns NULL at EOF
** Caller must free result
*/
static char *sqlite3_readline(const char *prompt){
  char buf[65536];
  char *z;
  int n;
  if(prompt && prompt[0]) {
    fputs(prompt, stdout);
    fflush(stdout);
  }
  if(fgets(buf, sizeof(buf), stdin)==NULL) return NULL;
  n = (int)strlen(buf);
  z = malloc(n+1);
  memcpy(z, buf, n+1);
  return z;
}

/* 
** Convert a string to lowercase in place
*/
static void toLower(char *z){
  while(*z){ *z = (char)tolower((unsigned char)*z); z++; }
}

/*
** Case-insensitive string comparison
*/
static int ci_cmp(const char *a, const char *b){
  while(*a && tolower((unsigned char)*a)==tolower((unsigned char)*b)){
    a++; b++;
  }
  return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}

static int ci_ncmp(const char *a, const char *b, int n){
  while(n-- && *a && tolower((unsigned char)*a)==tolower((unsigned char)*b)){
    a++; b++;
  }
  if(n<0) return 0;
  return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}

