** Print output to the current output file
*/
static void oputf(ShellState *p, const char *fmt, ...) {
  va_list ap;
  FILE *out = p->bOnce ? p->outOnce : p->out;
  va_start(ap, fmt);
  vfprintf(out, fmt, ap);
  va_end(ap);
}

static void oputs(ShellState *p, const char *s) {
