/*
** Version override functions
*/
static void version_func(sqlite3_context *ctx, int argc, sqlite3_value **argv){
  (void)argc; (void)argv;
  sqlite3_result_text(ctx, MY_SQLITE_VERSION, -1, SQLITE_STATIC);
}
static void sourceid_func(sqlite3_context *ctx, int argc, sqlite3_value **argv){
  (void)argc; (void)argv;
  sqlite3_result_text(ctx, MY_SQLITE_SOURCE_ID, -1, SQLITE_STATIC);
}
static void version_num_func(sqlite3_context *ctx, int argc, sqlite3_value **argv){
  (void)argc; (void)argv;
  sqlite3_result_int(ctx, SQLITE_VERSION_NUMBER);
}

static void registerVersionOverrides(sqlite3 *db){
  sqlite3_create_function(db, "sqlite_version", 0, SQLITE_UTF8, NULL,
    version_func, NULL, NULL);
  sqlite3_create_function(db, "sqlite_source_id", 0, SQLITE_UTF8, NULL,
    sourceid_func, NULL, NULL);
  sqlite3_create_function(db, "sqlite_version_number", 0, SQLITE_UTF8, NULL,
    version_num_func, NULL, NULL);
}

/*
** Open a database connection
*/
static int shellDbOpen(ShellState *p, const char *zFile, int bReadOnly){
  int rc;
  int flags;

  if(p->db){
    sqlite3_close(p->db);
    p->db = NULL;
  }

  if(!zFile) zFile = ":memory:";

  if(bReadOnly){
    flags = SQLITE_OPEN_READONLY;
  } else {
    flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE;
  }
  if(p->noFollow) flags |= SQLITE_OPEN_NOFOLLOW;

  rc = sqlite3_open_v2(zFile, &p->db, flags, NULL);
  if(rc != SQLITE_OK){
    eputf("Error: cannot open %s: %s\n", zFile, sqlite3_errmsg(p->db));
    sqlite3_close(p->db);
    p->db = NULL;
    return rc;
  }
  sqlite3_extended_result_codes(p->db, 1);
  if(p->progressStep > 0){
    /* Will be set later */
  }
  registerVersionOverrides(p->db);
  return SQLITE_OK;
}

/*
** Compute column widths for column mode
** Returns allocated array of widths
*/
static int *computeColWidths(ShellState *p, int nCol, char **headers,
                              char **azResult, int nRow){
  int *w = (int*)calloc(nCol, sizeof(int));
  int i, j;

  /* Set minimum widths from preset .width values */
  for(i=0; i<nCol; i++){
    if(i < p->nWidth && p->colWidth[i] != 0){
      w[i] = abs(p->colWidth[i]);
    } else {
      w[i] = 0;
    }
  }

  /* Width from headers */
  if(p->showHeader && headers){
    for(i=0; i<nCol; i++){
      int hlen = headers[i] ? (int)strlen(headers[i]) : 0;
      if(hlen > w[i]) w[i] = hlen;
    }
  }

  /* Width from data */
  for(j=0; j<nRow; j++){
    for(i=0; i<nCol; i++){
      const char *val = azResult ? azResult[j*nCol + i] : NULL;
      int vlen = val ? (int)strlen(val) : (int)strlen(p->nullValue);
      if(vlen > w[i]) w[i] = vlen;
    }
  }

  return w;
}

/*
** Print n spaces
*/
static void printSpaces(FILE *out, int n){
  while(n-- > 0) fputc(' ', out);
}

/*
** Print a horizontal separator line for table/box modes
*/
static void printTableSepLine(FILE *out, int *widths, int nCol,
                               const char *left, const char *mid,
                               const char *right, const char *fill){
  int i;
  fputs(left, out);
  for(i=0; i<nCol; i++){
    int j;
    for(j=0; j<widths[i]+2; j++) fputs(fill, out);
    if(i < nCol-1) fputs(mid, out);
  }
  fputs(right, out);
  fputc('\n', out);
}

/*
** Output a row in column/table/box/markdown mode
*/
static void outputRow(ShellState *p, int *widths, int *colTypes,
                      char **values, int nCol, int isHeader){
  FILE *out = p->bOnce ? p->outOnce : p->out;
  int i;

  if(p->mode == MODE_Column){
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int preset = (i < p->nWidth) ? p->colWidth[i] : 0;
      int rightAlign = (preset < 0) ||
                       (!isHeader && colTypes && colTypes[i] == SQLITE_INTEGER) ||
                       (!isHeader && colTypes && colTypes[i] == SQLITE_FLOAT);

      if(i > 0) fputs("  ", out);

      if(w <= 0) w = 10;

      if(preset != 0 && (int)strlen(v) > abs(preset)){
        /* Need to wrap - just truncate for now at word boundary */
        /* Actually for column mode with set width, wrap at w chars */
        int first = 1;
        const char *s = v;
        while(*s){
          int len = (int)strlen(s);
          if(first){
            if(rightAlign) printSpaces(out, w - (len < w ? len : w));
            fwrite(s, 1, len < w ? len : w, out);
            first = 0;
          } else {
            fputc('\n', out);
            /* indent for subsequent lines */
            for(int ci=0; ci<i; ci++){
              printSpaces(out, widths[ci] + 2);
            }
            fwrite(s, 1, len < w ? len : w, out);
          }
          if(len <= w) break;
          s += w;
        }
        /* Pad to width if first segment */
        if(!rightAlign){
          int vlen = (int)strlen(v);
          if(vlen < w) printSpaces(out, w - vlen);
        }
      } else {
        int vlen = (int)strlen(v);
        if(rightAlign){
          printSpaces(out, w - vlen);
          fputs(v, out);
        } else {
          fputs(v, out);
          if(i < nCol-1) printSpaces(out, w - vlen);
        }
      }
    }
    fputc('\n', out);

  } else if(p->mode == MODE_Table){
    fputs("| ", out);
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int vlen = (int)strlen(v);
      int rightAlign = (!isHeader && colTypes &&
                        (colTypes[i]==SQLITE_INTEGER || colTypes[i]==SQLITE_FLOAT));
      if(rightAlign){
        printSpaces(out, w - vlen);
        fputs(v, out);
      } else {
        fputs(v, out);
        printSpaces(out, w - vlen);
      }
      fputs(" | ", out);
    }
    fputc('\n', out);

  } else if(p->mode == MODE_Box){
    fputs("\342\224\202 ", out);
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int vlen = (int)strlen(v);
      int rightAlign = (!isHeader && colTypes &&
                        (colTypes[i]==SQLITE_INTEGER || colTypes[i]==SQLITE_FLOAT));
      if(rightAlign){
        printSpaces(out, w - vlen);
        fputs(v, out);
      } else {
        fputs(v, out);
        printSpaces(out, w - vlen);
      }
      fputs(" \342\224\202 ", out);
    }
    fputc('\n', out);

  } else if(p->mode == MODE_Markdown){
    fputs("| ", out);
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int vlen = (int)strlen(v);
      int rightAlign = (!isHeader && colTypes &&
                        (colTypes[i]==SQLITE_INTEGER || colTypes[i]==SQLITE_FLOAT));
      if(rightAlign){
        printSpaces(out, w - vlen);
        fputs(v, out);
      } else {
        fputs(v, out);
        printSpaces(out, w - vlen);
      }
      fputs(" | ", out);
    }
    fputc('\n', out);
  }
}

/*
** Output buffered column/table/box/markdown results
*/
static void flushBufferedResults(ShellState *p){
  FILE *out = p->bOnce ? p->outOnce : p->out;
  int i, j;
  int *widths;

  if(p->nResultCol == 0) return;

  widths = computeColWidths(p, p->nResultCol, p->azHeader,
                             p->azResult, p->nResultRow);

  if(p->mode == MODE_Column){
    /* Print headers */
    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      /* Print separator dashes */
      for(i=0; i<p->nResultCol; i++){
        if(i>0) fputs("  ", out);
        for(j=0; j<widths[i]; j++) fputc('-', out);
      }
      fputc('\n', out);
    }
    /* Print data rows */
    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }

  } else if(p->mode == MODE_Table){
    printTableSepLine(out, widths, p->nResultCol, "+", "+", "+", "-");
    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      printTableSepLine(out, widths, p->nResultCol, "+", "+", "+", "-");
    }
    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }
    printTableSepLine(out, widths, p->nResultCol, "+", "+", "+", "-");

  } else if(p->mode == MODE_Box){
    /* top border: ╭──┬──╮ */
    fputs("\342\225\255", out);
    for(i=0; i<p->nResultCol; i++){
      for(j=0; j<widths[i]+2; j++) fputs("\342\224\200", out);
      if(i < p->nResultCol-1) fputs("\342\224\254", out);
    }
    fputs("\342\225\256\n", out);

    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      /* header separator: ╞══╪══╡ */
      fputs("\342\225\236", out);
      for(i=0; i<p->nResultCol; i++){
        for(j=0; j<widths[i]+2; j++) fputs("\342\225\220", out);
        if(i < p->nResultCol-1) fputs("\342\225\252", out);
      }
      fputs("\342\225\241\n", out);
    }

    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }

    /* bottom border: ╰──┴──╯ */
    fputs("\342\225\260", out);
    for(i=0; i<p->nResultCol; i++){
      for(j=0; j<widths[i]+2; j++) fputs("\342\224\200", out);
      if(i < p->nResultCol-1) fputs("\342\224\264", out);
    }
    fputs("\342\225\257\n", out);

  } else if(p->mode == MODE_Markdown){
    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      /* separator: |---|---|  */
      fputs("|", out);
      for(i=0; i<p->nResultCol; i++){
        for(j=0; j<widths[i]+2; j++) fputc('-', out);
        fputc('|', out);
      }
      fputc('\n', out);
    }
    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }
  }

  free(widths);
}

/*
** Add a row to the buffer for column mode
*/
static void bufferRow(ShellState *p, int nCol, char **azVals, int *aTypes){
  int i;
  if(p->nResultRow == 0){
    p->nResultCol = nCol;
    p->azResult = NULL;
    p->nResultAlloc = 0;
    p->colTypes = (int*)malloc(nCol * sizeof(int));
    for(i=0; i<nCol; i++) p->colTypes[i] = aTypes ? aTypes[i] : SQLITE_TEXT;
  }
  if(p->nResultRow >= p->nResultAlloc){
    p->nResultAlloc = p->nResultAlloc * 2 + 16;
    p->azResult = (char**)realloc(p->azResult,
                  p->nResultAlloc * nCol * sizeof(char*));
  }
  for(i=0; i<nCol; i++){
    const char *v = azVals[i] ? azVals[i] : NULL;
    p->azResult[p->nResultRow * nCol + i] = v ? strdup(v) : NULL;
    if(aTypes && p->nResultRow == 0){
      /* Only set types from first row if not already set */
    }
  }
  /* Update colTypes to the widest type seen */
  if(aTypes){
    for(i=0; i<nCol; i++){
      if(aTypes[i] != SQLITE_NULL) p->colTypes[i] = aTypes[i];
    }
  }
  p->nResultRow++;
}

/*
** Clear the result buffer
*/
static void clearResultBuffer(ShellState *p){
  int i;
  if(p->azResult){
    for(i=0; i<p->nResultRow * p->nResultCol; i++) free(p->azResult[i]);
    free(p->azResult);
    p->azResult = NULL;
  }
  if(p->azHeader){
    for(i=0; i<p->nResultCol; i++) free(p->azHeader[i]);
    free(p->azHeader);
    p->azHeader = NULL;
  }
  free(p->colTypes);
  p->colTypes = NULL;
  p->nResultRow = 0;
  p->nResultCol = 0;
  p->nResultAlloc = 0;
}

/*
** Output a single value in the current mode
*/
static void printValue(ShellState *p, FILE *out, const char *z, int colType,
                       int col, int nCol, char **aCol){
  (void)aCol;
  if(p->mode == MODE_List){
    if(col > 0) fputs(p->colSeparator, out);
    fputs(z ? z : p->nullValue, out);
    if(col == nCol-1) fputs(p->rowSeparator, out);
  } else if(p->mode == MODE_Csv){
    if(col > 0) fputc(',', out);
    if(z==NULL){ /* null outputs as empty string in CSV */ }
    else { csvPrint(out, z, ","); }
    if(col == nCol-1) fputs("\r\n", out);
  } else if(p->mode == MODE_Tabs){
    if(col > 0) fputc('\t', out);
    fputs(z ? z : p->nullValue, out);
    if(col == nCol-1) fputc('\n', out);
  } else if(p->mode == MODE_Line){
    /* Handled elsewhere */
  } else if(p->mode == MODE_Quote){
    if(col > 0) fputc(',', out);
    if(z == NULL){
      fputs("NULL", out);
    } else if(colType == SQLITE_INTEGER || colType == SQLITE_FLOAT){
      fputs(z, out);
    } else if(colType == SQLITE_BLOB){
      /* Print as hex */
      fprintf(out, "X'");
      const unsigned char *s = (const unsigned char*)z;
      while(*s) fprintf(out, "%02X", *s++);
      fputc('\'', out);
    } else {
      /* Quote the string */
      fputc('\'', out);
      while(*z){
        if(*z == '\'') fputc('\'', out);
        fputc(*z, out);
        z++;
      }
      fputc('\'', out);
    }
    if(col == nCol-1) fputc('\n', out);
  } else if(p->mode == MODE_Insert){
    /* Handled separately */
  } else if(p->mode == MODE_Html){
    if(col == 0) fputs("<TR>\n", out);
    fputs("<TD>", out);
    htmlEncode(out, z ? z : p->nullValue);
    fputc('\n', out);
    if(col == nCol-1) fputs("</TR>\n", out);
  } else if(p->mode == MODE_Ascii){
    if(col > 0) fputc(0x1F, out);
    fputs(z ? z : p->nullValue, out);
    if(col == nCol-1) fputc(0x1E, out);
  } else if(p->mode == MODE_Tcl){
    if(col > 0) fputc(' ', out);
    if(z==NULL || z[0]==0){
      fputs("\"\"", out);
    } else {
      int needQuote = 0;
      const char *s = z;
      while(*s){
        if(*s==' '||*s=='\t'||*s=='\n'||*s=='\r'||*s=='"'||*s=='{'||*s=='}'||*s=='['||*s==']'||*s=='\\'){
          needQuote=1; break;
        }
        s++;
      }
      if(needQuote){
        fputc('"', out);
        while(*z){
          if(*z=='"'||*z=='\\'||*z=='['||*z==']') fputc('\\', out);
          fputc(*z, out);
          z++;
        }
        fputc('"', out);
      } else {
        fputs(z, out);
      }
    }
    if(col == nCol-1) fputc('\n', out);
  }
}

