** Caller must free result
*/
static char *sqlite3_readline(const char *prompt){
  char buf[65536];
  char *z;
  int n;
  if(prompt && prompt[0]) {
    fputs(prompt, stdout);
    fflush(stdout);
  }
  if(fgets(buf, sizeof(buf), stdin)==NULL) return NULL;
  n = (int)strlen(buf);
  z = malloc(n+1);
  memcpy(z, buf, n+1);
  return z;
}

