  int rowCount;        /* Row count for COUNT mode */
  int doTimer;         /* Show timing info */
  int explainPrev;     /* Previous explain mode */
  int explain;         /* Explain mode: 0=auto, 1=on, 2=off */
  int progressStep;    /* Progress handler step */
  int progressCnt;     /* Progress counter */
  int nProgress;       /* Number of progress callbacks */

  char mainPrompt[20];
  char continuePrompt[20];

  int interactive;     /* True if shell is interactive */
  int isBatch;         /* True in batch mode */

  /* For output buffering in column mode */
  char **azResult;     /* Buffered result rows */
  int nResultRow;      /* Number of result rows buffered */
  int nResultAlloc;    /* Allocated size of azResult */
  char **azHeader;     /* Column headers */
  int *colTypes;       /* Column types */
  int nResultCol;      /* Number of result columns */

  /* Shell exit code */
  int exitCode;
  int bExit;           /* True to exit */

  /* For log */
  FILE *pLog;

  /* For .once */
  FILE *outOnce;
  int bOnce;

  /* Line number tracking */
  int lineno;

  /* Bail on error */
  int bBail;

  /* readonly flag */
  int openReadOnly;

  /* nofollow flag */
  int noFollow;

  /* parameter bindings */
  BindParam *aParam;
  int nParam;
  int nParamAlloc;

  /* Multiple connections */
  sqlite3 *aConn[10]; /* Auxiliary connections */
  int nConn;
  int iConn;   /* Current connection (0=main) */

  /* screenwidth */
  int screenWidth;

  /* eqp output buffer */
  DynStr eqpStr;
  int eqpOn;      /* 0=off, 1=on, 2=full, 3=trigger */

  /* trace level */
  int traceMode;

} ShellState;

static volatile int seenInterrupt = 0;

static void interrupt_handler(int NotUsed){
  (void)NotUsed;
  seenInterrupt++;
  if( seenInterrupt>2 ) exit(1);
}

/*
** Interpret escape sequences in a string
*/
static char *interpretEscapes(const char *z) {
  static char buf[200];
  int i = 0;
  int j = 0;
  while (z[i] && j < 190) {
    if (z[i] == '\\' && z[i+1]) {
      i++;
      switch(z[i]) {
        case 'n': buf[j++] = '\n'; break;
        case 't': buf[j++] = '\t'; break;
        case 'r': buf[j++] = '\r'; break;
        case '\\': buf[j++] = '\\'; break;
        default: buf[j++] = '\\'; buf[j++] = z[i]; break;
      }
    } else {
      buf[j++] = z[i];
    }
    i++;
  }
  buf[j] = 0;
  return buf;
}

/*
** Get current time in microseconds
*/
static sqlite3_int64 timeOfDay(void){
  struct timeval tv;
  gettimeofday(&tv, 0);
  return (sqlite3_int64)(tv.tv_sec*1000000 + tv.tv_usec);
}

static sqlite3_int64 HiResTimer(void){ return timeOfDay(); }

/*
** HTML escape a string
*/
static void htmlEncode(FILE *out, const char *z){
  while(z && *z){
    if(*z == '<' || *z == '>'){
      fputs("&lt;", out);
    } else if(*z == '&'){
      fputs("&amp;", out);
    } else if(*z == '"'){
      fputs("&quot;", out);
    } else {
      fputc(*z, out);
    }
    z++;
  }
}

/*
** CSV escape
*/
static void csvPrint(FILE *out, const char *z, const char *sep){
  int needQuote = 0;
  if(z==NULL){ fputs("", out); return; }
  if(strchr(z,'"') || strchr(z,'\n') || strchr(z,'\r') || strstr(z,sep))
    needQuote = 1;
  if(!needQuote){ fputs(z, out); return; }
  fputc('"', out);
  while(*z){
    if(*z=='"') fputc('"', out);
    fputc(*z, out);
    z++;
  }
  fputc('"', out);
}

/*
** Read a line from stdin, returns NULL at EOF
** Caller must free result
*/
static char *sqlite3_readline(const char *prompt){
  char buf[65536];
  char *z;
  int n;
  if(prompt && prompt[0]) {
    fputs(prompt, stdout);
    fflush(stdout);
  }
  if(fgets(buf, sizeof(buf), stdin)==NULL) return NULL;
  n = (int)strlen(buf);
  z = malloc(n+1);
  memcpy(z, buf, n+1);
  return z;
}

/* 
** Convert a string to lowercase in place
*/
static void toLower(char *z){
  while(*z){ *z = (char)tolower((unsigned char)*z); z++; }
}

/*
** Case-insensitive string comparison
*/
static int ci_cmp(const char *a, const char *b){
  while(*a && tolower((unsigned char)*a)==tolower((unsigned char)*b)){
    a++; b++;
  }
  return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}

static int ci_ncmp(const char *a, const char *b, int n){
  while(n-- && *a && tolower((unsigned char)*a)==tolower((unsigned char)*b)){
    a++; b++;
  }
  if(n<0) return 0;
  return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}

/*
** Print output to the current output file
*/
static void oputf(ShellState *p, const char *fmt, ...) {
  va_list ap;
  FILE *out = p->bOnce ? p->outOnce : p->out;
  va_start(ap, fmt);
  vfprintf(out, fmt, ap);
  va_end(ap);
}

static void oputs(ShellState *p, const char *s) {
  FILE *out = p->bOnce ? p->outOnce : p->out;
  fputs(s, out);
}

/* eputf: error output */
static void eputf(const char *fmt, ...) {
  va_list ap;
  va_start(ap, fmt);
  vfprintf(stderr, fmt, ap);
  va_end(ap);
}

static void eputs(const char *s) {
  fputs(s, stderr);
}

/*
** Initialize a ShellState
*/
static void shellStateInit(ShellState *p) {
  memset(p, 0, sizeof(*p));
  p->out = stdout;
  p->mode = MODE_List;
  strcpy(p->colSeparator, "|");
  strcpy(p->rowSeparator, "\n");
  p->nullValue[0] = 0;
  p->showHeader = 0;
  p->bail = 0;
  strcpy(p->mainPrompt, "sqlite> ");
  strcpy(p->continuePrompt, "   ...> ");
  p->interactive = 0;
  p->screenWidth = 80;
  p->progressStep = 0;
}

/*
** Shell state cleanup
*/
static void shellStateFree(ShellState *p) {
  int i;
  free(p->zDbFilename);
  free(p->zInsertTable);
  for(i=0; i<p->nParam; i++){
    free(p->aParam[i].zName);
    free(p->aParam[i].zValue);
  }
  free(p->aParam);
  if(p->azResult){
    for(i=0; i<p->nResultRow*p->nResultCol; i++) free(p->azResult[i]);
    free(p->azResult);
  }
  if(p->azHeader){
    for(i=0; i<p->nResultCol; i++) free(p->azHeader[i]);
    free(p->azHeader);
  }
  free(p->colTypes);
  dynStrFree(&p->eqpStr);
}

/*
** Version override functions
*/
static void version_func(sqlite3_context *ctx, int argc, sqlite3_value **argv){
  (void)argc; (void)argv;
  sqlite3_result_text(ctx, MY_SQLITE_VERSION, -1, SQLITE_STATIC);
}
static void sourceid_func(sqlite3_context *ctx, int argc, sqlite3_value **argv){
  (void)argc; (void)argv;
  sqlite3_result_text(ctx, MY_SQLITE_SOURCE_ID, -1, SQLITE_STATIC);
}
static void version_num_func(sqlite3_context *ctx, int argc, sqlite3_value **argv){
  (void)argc; (void)argv;
  sqlite3_result_int(ctx, SQLITE_VERSION_NUMBER);
}

static void registerVersionOverrides(sqlite3 *db){
  sqlite3_create_function(db, "sqlite_version", 0, SQLITE_UTF8, NULL,
    version_func, NULL, NULL);
  sqlite3_create_function(db, "sqlite_source_id", 0, SQLITE_UTF8, NULL,
    sourceid_func, NULL, NULL);
  sqlite3_create_function(db, "sqlite_version_number", 0, SQLITE_UTF8, NULL,
    version_num_func, NULL, NULL);
}

/*
** Open a database connection
*/
static int shellDbOpen(ShellState *p, const char *zFile, int bReadOnly){
  int rc;
  int flags;

  if(p->db){
    sqlite3_close(p->db);
    p->db = NULL;
  }

  if(!zFile) zFile = ":memory:";

  if(bReadOnly){
    flags = SQLITE_OPEN_READONLY;
  } else {
    flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE;
  }
  if(p->noFollow) flags |= SQLITE_OPEN_NOFOLLOW;

  rc = sqlite3_open_v2(zFile, &p->db, flags, NULL);
  if(rc != SQLITE_OK){
    eputf("Error: cannot open %s: %s\n", zFile, sqlite3_errmsg(p->db));
    sqlite3_close(p->db);
    p->db = NULL;
    return rc;
  }
  sqlite3_extended_result_codes(p->db, 1);
  if(p->progressStep > 0){
    /* Will be set later */
  }
  registerVersionOverrides(p->db);
  return SQLITE_OK;
}

/*
** Compute column widths for column mode
** Returns allocated array of widths
*/
static int *computeColWidths(ShellState *p, int nCol, char **headers,
                              char **azResult, int nRow){
  int *w = (int*)calloc(nCol, sizeof(int));
  int i, j;

  /* Set minimum widths from preset .width values */
  for(i=0; i<nCol; i++){
    if(i < p->nWidth && p->colWidth[i] != 0){
      w[i] = abs(p->colWidth[i]);
    } else {
      w[i] = 0;
    }
  }

  /* Width from headers */
  if(p->showHeader && headers){
    for(i=0; i<nCol; i++){
      int hlen = headers[i] ? (int)strlen(headers[i]) : 0;
      if(hlen > w[i]) w[i] = hlen;
    }
  }

  /* Width from data */
  for(j=0; j<nRow; j++){
    for(i=0; i<nCol; i++){
      const char *val = azResult ? azResult[j*nCol + i] : NULL;
      int vlen = val ? (int)strlen(val) : (int)strlen(p->nullValue);
      if(vlen > w[i]) w[i] = vlen;
    }
  }

  return w;
}

/*
** Print n spaces
*/
static void printSpaces(FILE *out, int n){
  while(n-- > 0) fputc(' ', out);
}

/*
** Print a horizontal separator line for table/box modes
*/
static void printTableSepLine(FILE *out, int *widths, int nCol,
                               const char *left, const char *mid,
                               const char *right, const char *fill){
  int i;
  fputs(left, out);
  for(i=0; i<nCol; i++){
    int j;
    for(j=0; j<widths[i]+2; j++) fputs(fill, out);
    if(i < nCol-1) fputs(mid, out);
  }
  fputs(right, out);
  fputc('\n', out);
}

/*
** Output a row in column/table/box/markdown mode
*/
static void outputRow(ShellState *p, int *widths, int *colTypes,
                      char **values, int nCol, int isHeader){
  FILE *out = p->bOnce ? p->outOnce : p->out;
  int i;

  if(p->mode == MODE_Column){
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int preset = (i < p->nWidth) ? p->colWidth[i] : 0;
      int rightAlign = (preset < 0) ||
                       (!isHeader && colTypes && colTypes[i] == SQLITE_INTEGER) ||
                       (!isHeader && colTypes && colTypes[i] == SQLITE_FLOAT);

      if(i > 0) fputs("  ", out);

      if(w <= 0) w = 10;

      if(preset != 0 && (int)strlen(v) > abs(preset)){
        /* Need to wrap - just truncate for now at word boundary */
        /* Actually for column mode with set width, wrap at w chars */
        int first = 1;
        const char *s = v;
        while(*s){
          int len = (int)strlen(s);
          if(first){
            if(rightAlign) printSpaces(out, w - (len < w ? len : w));
            fwrite(s, 1, len < w ? len : w, out);
            first = 0;
          } else {
            fputc('\n', out);
            /* indent for subsequent lines */
            for(int ci=0; ci<i; ci++){
              printSpaces(out, widths[ci] + 2);
            }
            fwrite(s, 1, len < w ? len : w, out);
          }
          if(len <= w) break;
          s += w;
        }
        /* Pad to width if first segment */
        if(!rightAlign){
          int vlen = (int)strlen(v);
          if(vlen < w) printSpaces(out, w - vlen);
        }
      } else {
        int vlen = (int)strlen(v);
        if(rightAlign){
          printSpaces(out, w - vlen);
          fputs(v, out);
        } else {
          fputs(v, out);
          if(i < nCol-1) printSpaces(out, w - vlen);
        }
      }
    }
    fputc('\n', out);

  } else if(p->mode == MODE_Table){
    fputs("| ", out);
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int vlen = (int)strlen(v);
      int rightAlign = (!isHeader && colTypes &&
                        (colTypes[i]==SQLITE_INTEGER || colTypes[i]==SQLITE_FLOAT));
      if(rightAlign){
        printSpaces(out, w - vlen);
        fputs(v, out);
      } else {
        fputs(v, out);
        printSpaces(out, w - vlen);
      }
      fputs(" | ", out);
    }
    fputc('\n', out);

  } else if(p->mode == MODE_Box){
    fputs("\342\224\202 ", out);
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int vlen = (int)strlen(v);
      int rightAlign = (!isHeader && colTypes &&
                        (colTypes[i]==SQLITE_INTEGER || colTypes[i]==SQLITE_FLOAT));
      if(rightAlign){
        printSpaces(out, w - vlen);
        fputs(v, out);
      } else {
        fputs(v, out);
        printSpaces(out, w - vlen);
      }
      fputs(" \342\224\202 ", out);
    }
    fputc('\n', out);

  } else if(p->mode == MODE_Markdown){
    fputs("| ", out);
    for(i=0; i<nCol; i++){
      const char *v = values[i] ? values[i] : p->nullValue;
      int w = widths[i];
      int vlen = (int)strlen(v);
      int rightAlign = (!isHeader && colTypes &&
                        (colTypes[i]==SQLITE_INTEGER || colTypes[i]==SQLITE_FLOAT));
      if(rightAlign){
        printSpaces(out, w - vlen);
        fputs(v, out);
      } else {
        fputs(v, out);
        printSpaces(out, w - vlen);
      }
      fputs(" | ", out);
    }
    fputc('\n', out);
  }
}

/*
** Output buffered column/table/box/markdown results
*/
static void flushBufferedResults(ShellState *p){
  FILE *out = p->bOnce ? p->outOnce : p->out;
  int i, j;
  int *widths;

  if(p->nResultCol == 0) return;

  widths = computeColWidths(p, p->nResultCol, p->azHeader,
                             p->azResult, p->nResultRow);

  if(p->mode == MODE_Column){
    /* Print headers */
    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      /* Print separator dashes */
      for(i=0; i<p->nResultCol; i++){
        if(i>0) fputs("  ", out);
        for(j=0; j<widths[i]; j++) fputc('-', out);
      }
      fputc('\n', out);
    }
    /* Print data rows */
    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }

  } else if(p->mode == MODE_Table){
    printTableSepLine(out, widths, p->nResultCol, "+", "+", "+", "-");
    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      printTableSepLine(out, widths, p->nResultCol, "+", "+", "+", "-");
    }
    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }
    printTableSepLine(out, widths, p->nResultCol, "+", "+", "+", "-");

  } else if(p->mode == MODE_Box){
    /* top border: ╭──┬──╮ */
    fputs("\342\225\255", out);
    for(i=0; i<p->nResultCol; i++){
      for(j=0; j<widths[i]+2; j++) fputs("\342\224\200", out);
      if(i < p->nResultCol-1) fputs("\342\224\254", out);
    }
    fputs("\342\225\256\n", out);

    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      /* header separator: ╞══╪══╡ */
      fputs("\342\225\236", out);
      for(i=0; i<p->nResultCol; i++){
        for(j=0; j<widths[i]+2; j++) fputs("\342\225\220", out);
        if(i < p->nResultCol-1) fputs("\342\225\252", out);
      }
      fputs("\342\225\241\n", out);
    }

    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }

    /* bottom border: ╰──┴──╯ */
    fputs("\342\225\260", out);
    for(i=0; i<p->nResultCol; i++){
      for(j=0; j<widths[i]+2; j++) fputs("\342\224\200", out);
      if(i < p->nResultCol-1) fputs("\342\224\264", out);
    }
    fputs("\342\225\257\n", out);

  } else if(p->mode == MODE_Markdown){
    if(p->showHeader && p->azHeader){
      outputRow(p, widths, NULL, p->azHeader, p->nResultCol, 1);
      /* separator: |---|---|  */
      fputs("|", out);
      for(i=0; i<p->nResultCol; i++){
        for(j=0; j<widths[i]+2; j++) fputc('-', out);
        fputc('|', out);
      }
      fputc('\n', out);
    }
    for(j=0; j<p->nResultRow; j++){
      outputRow(p, widths, p->colTypes,
                p->azResult + j*p->nResultCol, p->nResultCol, 0);
    }
  }

  free(widths);
}

/*
** Add a row to the buffer for column mode
*/
static void bufferRow(ShellState *p, int nCol, char **azVals, int *aTypes){
  int i;
  if(p->nResultRow == 0){
    p->nResultCol = nCol;
    p->azResult = NULL;
    p->nResultAlloc = 0;
    p->colTypes = (int*)malloc(nCol * sizeof(int));
    for(i=0; i<nCol; i++) p->colTypes[i] = aTypes ? aTypes[i] : SQLITE_TEXT;
  }
  if(p->nResultRow >= p->nResultAlloc){
    p->nResultAlloc = p->nResultAlloc * 2 + 16;
    p->azResult = (char**)realloc(p->azResult,
                  p->nResultAlloc * nCol * sizeof(char*));
  }
  for(i=0; i<nCol; i++){
    const char *v = azVals[i] ? azVals[i] : NULL;
    p->azResult[p->nResultRow * nCol + i] = v ? strdup(v) : NULL;
    if(aTypes && p->nResultRow == 0){
      /* Only set types from first row if not already set */
    }
  }
  /* Update colTypes to the widest type seen */
  if(aTypes){
    for(i=0; i<nCol; i++){
      if(aTypes[i] != SQLITE_NULL) p->colTypes[i] = aTypes[i];
    }
  }
  p->nResultRow++;
}

/*
** Clear the result buffer
*/
static void clearResultBuffer(ShellState *p){
  int i;
  if(p->azResult){
    for(i=0; i<p->nResultRow * p->nResultCol; i++) free(p->azResult[i]);
    free(p->azResult);
    p->azResult = NULL;
  }
  if(p->azHeader){
    for(i=0; i<p->nResultCol; i++) free(p->azHeader[i]);
    free(p->azHeader);
    p->azHeader = NULL;
  }
  free(p->colTypes);
  p->colTypes = NULL;
  p->nResultRow = 0;
  p->nResultCol = 0;
  p->nResultAlloc = 0;
}

/*
** Output a single value in the current mode
*/
static void printValue(ShellState *p, FILE *out, const char *z, int colType,
                       int col, int nCol, char **aCol){
  (void)aCol;
  if(p->mode == MODE_List){
    if(col > 0) fputs(p->colSeparator, out);
    fputs(z ? z : p->nullValue, out);
    if(col == nCol-1) fputs(p->rowSeparator, out);
  } else if(p->mode == MODE_Csv){
    if(col > 0) fputc(',', out);
    if(z==NULL){ /* null outputs as empty string in CSV */ }
    else { csvPrint(out, z, ","); }
    if(col == nCol-1) fputs("\r\n", out);
  } else if(p->mode == MODE_Tabs){
    if(col > 0) fputc('\t', out);
    fputs(z ? z : p->nullValue, out);
    if(col == nCol-1) fputc('\n', out);
  } else if(p->mode == MODE_Line){
    /* Handled elsewhere */
  } else if(p->mode == MODE_Quote){
    if(col > 0) fputc(',', out);
    if(z == NULL){
      fputs("NULL", out);
    } else if(colType == SQLITE_INTEGER || colType == SQLITE_FLOAT){
      fputs(z, out);
    } else if(colType == SQLITE_BLOB){
      /* Print as hex */
      fprintf(out, "X'");
      const unsigned char *s = (const unsigned char*)z;
      while(*s) fprintf(out, "%02X", *s++);
      fputc('\'', out);
    } else {
      /* Quote the string */
      fputc('\'', out);
      while(*z){
        if(*z == '\'') fputc('\'', out);
        fputc(*z, out);
        z++;
      }
      fputc('\'', out);
    }
    if(col == nCol-1) fputc('\n', out);
  } else if(p->mode == MODE_Insert){
    /* Handled separately */
  } else if(p->mode == MODE_Html){
    if(col == 0) fputs("<TR>\n", out);
    fputs("<TD>", out);
    htmlEncode(out, z ? z : p->nullValue);
    fputc('\n', out);
    if(col == nCol-1) fputs("</TR>\n", out);
  } else if(p->mode == MODE_Ascii){
    if(col > 0) fputc(0x1F, out);
    fputs(z ? z : p->nullValue, out);
    if(col == nCol-1) fputc(0x1E, out);
  } else if(p->mode == MODE_Tcl){
    if(col > 0) fputc(' ', out);
    if(z==NULL || z[0]==0){
      fputs("\"\"", out);
    } else {
      int needQuote = 0;
      const char *s = z;
      while(*s){
        if(*s==' '||*s=='\t'||*s=='\n'||*s=='\r'||*s=='"'||*s=='{'||*s=='}'||*s=='['||*s==']'||*s=='\\'){
          needQuote=1; break;
        }
        s++;
      }
      if(needQuote){
        fputc('"', out);
        while(*z){
          if(*z=='"'||*z=='\\'||*z=='['||*z==']') fputc('\\', out);
          fputc(*z, out);
          z++;
        }
        fputc('"', out);
      } else {
        fputs(z, out);
      }
    }
    if(col == nCol-1) fputc('\n', out);
  }
}

