/* Dynamic string */
typedef struct DynStr {
  char *z;
  int n;
  int nAlloc;
} DynStr;

static void dynStrInit(DynStr *p) {
  p->z = NULL; p->n = 0; p->nAlloc = 0;
}
static void dynStrAppendN(DynStr *p, const char *s, int n) {
  if (p->n + n + 1 > p->nAlloc) {
    int newSz = p->nAlloc * 2 + n + 100;
    p->z = realloc(p->z, newSz);
    p->nAlloc = newSz;
  }
  memcpy(p->z + p->n, s, n);
  p->n += n;
  p->z[p->n] = 0;
}
static void dynStrAppend(DynStr *p, const char *s) {
  dynStrAppendN(p, s, (int)strlen(s));
}
static void dynStrFree(DynStr *p) {
