}

/*
** Shell state cleanup
*/
static void shellStateFree(ShellState *p) {
  int i;
  free(p->zDbFilename);
  free(p->zInsertTable);
  for(i=0; i<p->nParam; i++){
    free(p->aParam[i].zName);
    free(p->aParam[i].zValue);
  }
  free(p->aParam);
