  int firstRow;
  sqlite3_int64 tStart; /* Timer start */
} CallbackData;

/*
** Execute SQL with full output formatting
** Uses step-by-step preparation for proper type detection
*/
static int runSqlStatement(ShellState *p, const char *zSql, int *pErrCount){
  sqlite3_stmt *pStmt = NULL;
  int rc;
  FILE *out = p->bOnce ? p->outOnce : p->out;
  int firstRow = 1;
  int nCol = 0;
  int jsonFirst = 1;
  sqlite3_int64 tStart = 0;

  if(p->doTimer) tStart = timeOfDay();

  rc = sqlite3_prepare_v2(p->db, zSql, -1, &pStmt, NULL);
  if(rc != SQLITE_OK){
    if(p->pLog) fprintf(p->pLog, "SQL error: %s\n", sqlite3_errmsg(p->db));
    return rc;
  }
  if(pStmt == NULL){
    return SQLITE_OK;
  }

  nCol = sqlite3_column_count(pStmt);

  /* For column/table/box/markdown modes, buffer all rows */
  if(p->mode == MODE_Column || p->mode == MODE_Table || 
     p->mode == MODE_Box || p->mode == MODE_Markdown){
    /* Set headers */
    if(nCol > 0){
      clearResultBuffer(p);
      p->nResultCol = nCol;
      p->azHeader = (char**)malloc(nCol * sizeof(char*));
      p->colTypes = (int*)calloc(nCol, sizeof(int));
      for(int i=0; i<nCol; i++){
        const char *h = sqlite3_column_name(pStmt, i);
        p->azHeader[i] = h ? strdup(h) : strdup("");
        p->colTypes[i] = SQLITE_TEXT;
      }

      /* Show HTML headers if needed */
      if(p->showHeader && p->mode == MODE_Html){
        fputs("<TR>\n", out);
        for(int i=0; i<nCol; i++){
          fputs("<TH>", out);
          htmlEncode(out, p->azHeader[i]);
          fputc('\n', out);
        }
        fputs("</TR>\n", out);
      }
    }

    while((rc = sqlite3_step(pStmt)) == SQLITE_ROW){
      char **azVals = (char**)malloc(nCol * sizeof(char*));
      int *aTypes = (int*)malloc(nCol * sizeof(int));
      char **azBufs = (char**)calloc(nCol, sizeof(char*));

      for(int i=0; i<nCol; i++){
        int t = sqlite3_column_type(pStmt, i);
        aTypes[i] = t;
        if(p->nResultRow == 0) p->colTypes[i] = t;
        else if(t != SQLITE_NULL) p->colTypes[i] = t;

        if(t == SQLITE_NULL){
          azVals[i] = NULL;
        } else {
          const unsigned char *txt = sqlite3_column_text(pStmt, i);
          azVals[i] = txt ? strdup((const char*)txt) : strdup("");
          azBufs[i] = azVals[i];
        }
      }
      bufferRow(p, nCol, azVals, aTypes);
      for(int i=0; i<nCol; i++) free(azBufs[i]);
      free(azVals);
      free(aTypes);
      free(azBufs);
    }

    if(rc == SQLITE_DONE){
      flushBufferedResults(p);
      clearResultBuffer(p);
      rc = SQLITE_OK;
    }

  } else if(p->mode == MODE_Json){
    /* JSON mode */
    if(p->showHeader){} /* JSON doesn't use headers flag */
    char **colNames = (char**)malloc(nCol * sizeof(char*));
    for(int i=0; i<nCol; i++){
      const char *h = sqlite3_column_name(pStmt, i);
      colNames[i] = h ? strdup(h) : strdup("");
    }

    fputs("[", out);
    jsonFirst = 1;
    while((rc = sqlite3_step(pStmt)) == SQLITE_ROW){
      if(!jsonFirst) fputs(",\n", out);
      else jsonFirst = 0;
      fputs("{", out);
      for(int i=0; i<nCol; i++){
        if(i>0) fputs(",", out);
        /* Key */
        fputc('"', out);
        const char *k = colNames[i];
        while(*k){
          if(*k=='"') fputs("\\\"", out);
          else if(*k=='\\') fputs("\\\\", out);
          else if(*k=='\n') fputs("\\n", out);
          else if(*k=='\r') fputs("\\r", out);
          else if(*k=='\t') fputs("\\t", out);
          else fputc(*k, out);
          k++;
        }
        fputs("\":", out);

        int t = sqlite3_column_type(pStmt, i);
        if(t == SQLITE_NULL){
          fputs("null", out);
        } else if(t == SQLITE_INTEGER){
          fprintf(out, "%lld", (long long)sqlite3_column_int64(pStmt, i));
        } else if(t == SQLITE_FLOAT){
          double d = sqlite3_column_double(pStmt, i);
          if(d != d || d*0.0 != 0.0){
            fputs("null", out); /* NaN/Inf */
          } else {
            fprintf(out, "%!.15g", d);
            /* Use proper format */
            char buf[64];
            snprintf(buf, sizeof(buf), "%.15g", d);
            /* Remove trailing zeros after decimal point but keep at least one digit */
            fputs(buf, out);
          }
        } else if(t == SQLITE_BLOB){
          int nb = sqlite3_column_bytes(pStmt, i);
          const unsigned char *zb = (const unsigned char*)sqlite3_column_blob(pStmt, i);
          fputc('"', out);
          for(int bi=0; bi<nb; bi++){
            fprintf(out, "\\u%04x", zb[bi]);
          }
          fputc('"', out);
        } else {
          /* Text */
          const unsigned char *txt = sqlite3_column_text(pStmt, i);
          fputc('"', out);
          if(txt) {
            const unsigned char *s = txt;
            while(*s){
              unsigned char c = *s;
              if(c == '"') fputs("\\\"", out);
              else if(c == '\\') fputs("\\\\", out);
              else if(c == '\n') fputs("\\n", out);
              else if(c == '\r') fputs("\\r", out);
              else if(c == '\t') fputs("\\t", out);
              else if(c < 0x20) fprintf(out, "\\u%04x", c);
              else fputc(c, out);
              s++;
            }
          }
          fputc('"', out);
        }
      }
      fputs("}", out);
    }
    fputs("]\n", out);
    for(int i=0; i<nCol; i++) free(colNames[i]);
    free(colNames);
    if(rc == SQLITE_DONE) rc = SQLITE_OK;

  } else if(p->mode == MODE_Html){
    /* HTML mode - headers first */
    if(p->showHeader && nCol > 0){
      fputs("<TR>\n", out);
      for(int i=0; i<nCol; i++){
        const char *h = sqlite3_column_name(pStmt, i);
        fputs("<TH>", out);
        htmlEncode(out, h ? h : "");
        fputc('\n', out);
      }
      fputs("</TR>\n", out);
    }
    while((rc = sqlite3_step(pStmt)) == SQLITE_ROW){
      fputs("<TR>\n", out);
      for(int i=0; i<nCol; i++){
        int t = sqlite3_column_type(pStmt, i);
        fputs("<TD>", out);
        if(t == SQLITE_NULL){
          htmlEncode(out, p->nullValue);
        } else {
          const char *v = (const char*)sqlite3_column_text(pStmt, i);
          htmlEncode(out, v ? v : "");
        }
        fputc('\n', out);
      }
      fputs("</TR>\n", out);
    }
    if(rc == SQLITE_DONE) rc = SQLITE_OK;

  } else if(p->mode == MODE_Insert){
    const char *tbl = p->zInsertTable ? p->zInsertTable : "tab";
    while((rc = sqlite3_step(pStmt)) == SQLITE_ROW){
      fprintf(out, "INSERT INTO %s VALUES(", tbl);
      for(int i=0; i<nCol; i++){
        if(i>0) fputc(',', out);
        int t = sqlite3_column_type(pStmt, i);
        if(t == SQLITE_NULL){
          fputs("NULL", out);
        } else if(t == SQLITE_INTEGER){
          fprintf(out, "%lld", (long long)sqlite3_column_int64(pStmt, i));
        } else if(t == SQLITE_FLOAT){
          fprintf(out, "%!g", sqlite3_column_double(pStmt, i));
          char buf[64];
          snprintf(buf, sizeof(buf), "%g", sqlite3_column_double(pStmt, i));
          fputs(buf, out);
        } else if(t == SQLITE_BLOB){
          int nb = sqlite3_column_bytes(pStmt, i);
          const unsigned char *zb = (const unsigned char*)sqlite3_column_blob(pStmt, i);
          fputs("X'", out);
          for(int bi=0; bi<nb; bi++) fprintf(out, "%02X", zb[bi]);
          fputc('\'', out);
        } else {
          const char *v = (const char*)sqlite3_column_text(pStmt, i);
          fputc('\'', out);
          if(v) while(*v){
            if(*v=='\'') fputc('\'', out);
            fputc(*v, out); v++;
          }
          fputc('\'', out);
        }
      }
      fputs(");\n", out);
    }
    if(rc == SQLITE_DONE) rc = SQLITE_OK;

  } else if(p->mode == MODE_Line){
    /* Line mode: name: value */
    while((rc = sqlite3_step(pStmt)) == SQLITE_ROW){
      if(!firstRow) fputc('\n', out);
      firstRow = 0;
      for(int i=0; i<nCol; i++){
        const char *name = sqlite3_column_name(pStmt, i);
        int t = sqlite3_column_type(pStmt, i);
        const char *v;
        if(t == SQLITE_NULL) v = p->nullValue;
        else v = (const char*)sqlite3_column_text(pStmt, i);
        /* Find longest name for alignment */
        fprintf(out, "%s = %s\n", name ? name : "", v ? v : "");
      }
    }
    if(rc == SQLITE_DONE) rc = SQLITE_OK;

  } else {
    /* List, CSV, Quote, Tabs, TCL, ASCII, etc. */
    /* Show headers if needed */
    if(p->showHeader && nCol > 0){
      if(p->mode == MODE_Csv){
        for(int i=0; i<nCol; i++){
          if(i>0) fputc(',', out);
          const char *h = sqlite3_column_name(pStmt, i);
          csvPrint(out, h ? h : "", ",");
        }
        fputs("\r\n", out);
      } else if(p->mode == MODE_Tcl){
        for(int i=0; i<nCol; i++){
          if(i>0) fputc(' ', out);
          const char *h = sqlite3_column_name(pStmt, i);
          fprintf(out, "\"%s\"", h ? h : "");
        }
        fputc('\n', out);
      } else if(p->mode == MODE_Html){
        /* done above */
      } else {
        for(int i=0; i<nCol; i++){
          if(i>0) fputs(p->colSeparator, out);
          const char *h = sqlite3_column_name(pStmt, i);
          fputs(h ? h : "", out);
        }
        fputs(p->rowSeparator, out);
      }
    }

    while((rc = sqlite3_step(pStmt)) == SQLITE_ROW){
      for(int i=0; i<nCol; i++){
        int t = sqlite3_column_type(pStmt, i);
        const char *v;
        if(t == SQLITE_NULL) v = NULL;
        else v = (const char*)sqlite3_column_text(pStmt, i);
        printValue(p, out, v, t, i, nCol, NULL);
      }
    }
    if(rc == SQLITE_DONE) rc = SQLITE_OK;
  }

  if(rc != SQLITE_OK && rc != SQLITE_DONE){
    /* Error occurred during stepping */
  }

  sqlite3_finalize(pStmt);

  if(p->doTimer && tStart > 0){
    sqlite3_int64 tEnd = timeOfDay();
    double elapsed = (tEnd - tStart) / 1000000.0;
    fprintf(stderr, "Run Time: real %.6f user %.6f sys %.6f\n",
            elapsed, 0.0, elapsed > 0 ? elapsed * 0.001 : 0.0);
  }

  return rc;
}

