/* ============================================================
** Version strings
** ============================================================ */
#define SQLITE_VERSION_OVERRIDE    "3.54.0"
#define SQLITE_SOURCE_ID_OVERRIDE  \
  "2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b"
#define SQLITE_VERSION_NUM_OVERRIDE 3054000

/* ============================================================
** Output Modes
** ============================================================ */
#define MODE_List       0
#define MODE_Column     1
#define MODE_Insert     2
#define MODE_Line       3
#define MODE_Html       4
#define MODE_Tcl        5
#define MODE_Csv        6
#define MODE_Explain    7
#define MODE_Ascii      8
#define MODE_Pretty     9
#define MODE_EQP       10
#define MODE_Json      11
#define MODE_Markdown  12
#define MODE_Table     13
#define MODE_Box       14
#define MODE_Count     15
#define MODE_Quote     16
#define MODE_Tabs      17

/* Number of output modes */
#define MODE_MAX  18

static const char *modeName[] = {
  "list", "column", "insert", "line", "html", "tcl", "csv",
  "explain", "ascii", "prettyprint", "eqp", "json", "markdown",
  "table", "box", "count", "quote", "tabs"
};

/* ============================================================
** Global state
** ============================================================ */
static volatile int seenInterrupt = 0;

static void interrupt_handler(int notused){
  (void)notused;
  seenInterrupt++;
  if(seenInterrupt>2) exit(1);
}

/* ============================================================
** Dynamic string type
** ============================================================ */
typedef struct StrBuf {
  char *z;
  int n;
  int sz;
} StrBuf;

static void sb_init(StrBuf *p){ p->z=NULL; p->n=0; p->sz=0; }

static void sb_append_n(StrBuf *p, const char *s, int n){
  if(n<0) n=(int)strlen(s);
  if(p->n+n+1 > p->sz){
    p->sz = p->sz*2 + n + 64;
    p->z = (char*)realloc(p->z, p->sz);
  }
  memcpy(p->z+p->n, s, n);
  p->n += n;
  p->z[p->n] = 0;
}

static void sb_append(StrBuf *p, const char *s){ sb_append_n(p, s, -1); }

static void sb_appendf(StrBuf *p, const char *fmt, ...){
  char buf[2048];
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  sb_append(p, buf);
}

static void sb_free(StrBuf *p){ free(p->z); p->z=NULL; p->n=0; p->sz=0; }

/* ============================================================
** Parameter bindings
** ============================================================ */
typedef struct Param {
  char *zName;
  char *zValue;
} Param;

/* ============================================================
** EQP Node for tree rendering
** ============================================================ */
typedef struct EQPGraphRow {
  int iEqpId;
  int iParentId;
  char zText[200];
  struct EQPGraphRow *pNext;
} EQPGraphRow;

typedef struct EQPGraph {
  EQPGraphRow *pRow;
  EQPGraphRow *pLast;
  char zPrefix[100];
} EQPGraph;

/* ============================================================
** Main ShellState structure
** ============================================================ */
typedef struct ShellState {
  sqlite3     *db;           /* The database */
  char        *zDbFilename;  /* Name of the database file */
  FILE        *out;          /* Output stream */
  int          mode;         /* Output mode (MODE_*) */
  int          showHeader;   /* Show column headers */
  char         colSep[20];   /* Column separator */
  char         rowSep[20];   /* Row separator */
  char         nullValue[40];/* NULL display string */
  int          colWidth[100];/* Requested column widths (0=auto) */
  int          nWidth;       /* Number of set widths */
