  int          printChanges; /* .changes */
  int          echoOn;       /* .echo */
  int          statsOn;      /* .stats */
  int          scanstatsOn;  /* .scanstats */
  char         zInsertTable[100]; /* Table for INSERT mode */
  int          doTimer;      /* .timer */
  int          doOnce;       /* Output next query to file */
  FILE        *outOnce;      /* File for .once */
