} ShellState;

/* ============================================================
** Version override SQL functions
** ============================================================ */
static void fnVersion(sqlite3_context *ctx, int ac, sqlite3_value **av){
  (void)ac; (void)av;
  sqlite3_result_text(ctx, SQLITE_VERSION_OVERRIDE, -1, SQLITE_STATIC);
}
static void fnSourceId(sqlite3_context *ctx, int ac, sqlite3_value **av){
  (void)ac; (void)av;
  sqlite3_result_text(ctx, SQLITE_SOURCE_ID_OVERRIDE, -1, SQLITE_STATIC);
}

static void registerVersionFuncs(sqlite3 *db){
  sqlite3_create_function(db, "sqlite_version", 0, SQLITE_UTF8,
    NULL, fnVersion, NULL, NULL);
  sqlite3_create_function(db, "sqlite_source_id", 0, SQLITE_UTF8,
    NULL, fnSourceId, NULL, NULL);
}

/* ============================================================
** Shell init / open db
** ============================================================ */
static void shellInit(ShellState *p){
  memset(p, 0, sizeof(*p));
  p->out = stdout;
  p->mode = MODE_List;
  strcpy(p->colSep, "|");
  strcpy(p->rowSep, "\n");
  p->nullValue[0] = 0;
  p->showHeader = 0;
  strcpy(p->mainPrompt, "sqlite> ");
  strcpy(p->contPrompt, "   ...> ");
  p->screenWidth = 80;
}

static int openDb(ShellState *p, const char *zFile, int readOnly){
  int flags = readOnly ? SQLITE_OPEN_READONLY :
              (SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE);
  int rc;
  if(p->noFollow) flags |= SQLITE_OPEN_NOFOLLOW;
  if(!zFile) zFile = ":memory:";
  rc = sqlite3_open_v2(zFile, &p->db, flags, NULL);
  if(rc){
    fprintf(stderr, "Error: cannot open %s: %s\n", zFile, sqlite3_errmsg(p->db));
    sqlite3_close(p->db);
    p->db = NULL;
    return rc;
  }
  sqlite3_extended_result_codes(p->db, 1);
  registerVersionFuncs(p->db);
  if(p->progressStep > 0){
    /* progress handler set later */
  }
  return SQLITE_OK;
}

/* ============================================================
** Output helpers
** ============================================================ */
static FILE *outFile(ShellState *p){
  return (p->doOnce && p->outOnce) ? p->outOnce : p->out;
}

static void oputf(ShellState *p, const char *fmt, ...){
  va_list ap;
  FILE *f = outFile(p);
  va_start(ap, fmt);
  vfprintf(f, fmt, ap);
  va_end(ap);
}

static void oputs(ShellState *p, const char *s){
  fputs(s, outFile(p));
}

static void oputc(ShellState *p, int c){
  fputc(c, outFile(p));
}

/* ============================================================
** HTML encoding
** ============================================================ */
static void htmlEsc(FILE *f, const char *z){
  if(!z) return;
  while(*z){
    if(*z=='<' || *z=='>') fputs("&lt;", f);
    else if(*z=='&') fputs("&amp;", f);
    else if(*z=='"') fputs("&quot;", f);
    else fputc(*z, f);
    z++;
  }
}

/* ============================================================
** CSV printing
** ============================================================ */
static void csvPrint(FILE *f, const char *z){
  int needQ = 0;
  const char *s = z;
  if(!z){ return; }
  while(*s){
    if(*s=='"' || *s=='\n' || *s=='\r' || *s==','){needQ=1; break;}
    s++;
  }
  if(!needQ){ fputs(z, f); return; }
  fputc('"', f);
  while(*z){
    if(*z=='"') fputc('"', f);
    fputc(*z, f);
    z++;
  }
  fputc('"', f);
}

/* ============================================================
** Timer
** ============================================================ */
static sqlite3_int64 timeUs(void){
  struct timeval tv;
  gettimeofday(&tv, NULL);
  return (sqlite3_int64)(tv.tv_sec)*1000000 + tv.tv_usec;
}

/* ============================================================
** Progress handler
** ============================================================ */
static int shellProgress(void *pV){
  ShellState *p = (ShellState*)pV;
  p->nProgress++;
  fprintf(stderr, "Progress %d\n", p->nProgress);
  if(seenInterrupt) return 1;
  return 0;
}

/* ============================================================
** Print N spaces
** ============================================================ */
static void printSpaces(FILE *f, int n){
  while(n-- > 0) fputc(' ', f);
}

/* ============================================================
** Column mode: compute widths from buffered data
** ============================================================ */
typedef struct ColBuf {
  int   nCol;
  int   nRow;
  int   nAlloc;
  char **azData;    /* nRow * nCol values (NULL = SQL NULL) */
  char **azHeader;  /* nCol headers */
  int  *aType;      /* nCol types (dominant non-null type per col) */
  int  *aPreType;   /* nCol preset type from decltype */
} ColBuf;

static void colBufInit(ColBuf *c){
  memset(c, 0, sizeof(*c));
}

static void colBufFree(ColBuf *c){
  int i;
  for(i=0;i<c->nCol;i++){
    free(c->azHeader[i]);
  }
  free(c->azHeader);
  for(i=0;i<c->nRow*c->nCol;i++) free(c->azData[i]);
  free(c->azData);
  free(c->aType);
  free(c->aPreType);
  memset(c, 0, sizeof(*c));
}

static void colBufAddRow(ColBuf *c, sqlite3_stmt *stmt){
  int i;
  if(c->nRow >= c->nAlloc){
    c->nAlloc = c->nAlloc*2 + 16;
    c->azData = (char**)realloc(c->azData, c->nAlloc*c->nCol*sizeof(char*));
  }
  for(i=0;i<c->nCol;i++){
    int t = sqlite3_column_type(stmt, i);
    const char *v = (const char*)sqlite3_column_text(stmt, i);
    c->azData[c->nRow*c->nCol+i] = (t==SQLITE_NULL) ? NULL : (v ? strdup(v) : strdup(""));
    if(t != SQLITE_NULL && c->aType[i]==SQLITE_NULL) c->aType[i] = t;
    else if(t==SQLITE_FLOAT && c->aType[i]==SQLITE_INTEGER) c->aType[i]=SQLITE_FLOAT;
  }
  c->nRow++;
}

/* ============================================================
** Column widths computation
** ============================================================ */
static void computeWidths(ShellState *p, ColBuf *c, int *wOut){
  int i, j;
  for(i=0;i<c->nCol;i++){
    int w = 0;
    /* From preset */
    if(i < p->nWidth && p->colWidth[i] != 0)
      w = abs(p->colWidth[i]);
    /* From header */
    if(p->showHeader && c->azHeader[i]){
      int h = (int)strlen(c->azHeader[i]);
      if(h > w) w = h;
    }
    /* From data */
    for(j=0;j<c->nRow;j++){
      const char *v = c->azData[j*c->nCol+i];
      int vl = v ? (int)strlen(v) : (int)strlen(p->nullValue);
      if(vl > w) w = vl;
    }
    wOut[i] = w;
  }
}

/* ============================================================
** Is value right-aligned?
** ============================================================ */
static int isRightAlign(ShellState *p, int col, ColBuf *c, int isHeader){
  if(isHeader) return 0;
  int preset = (col < p->nWidth) ? p->colWidth[col] : 0;
  if(preset < 0) return 1;
  int t = c->aType[col];
  return (t==SQLITE_INTEGER || t==SQLITE_FLOAT);
}

/* ============================================================
** Output columnar row
** ============================================================ */
static void outputColRow(ShellState *p, int *widths, ColBuf *c,
                          char **vals, int isHeader, FILE *f){
  int i;
  int nCol = c->nCol;
  if(p->mode == MODE_Column){
    for(i=0;i<nCol;i++){
      const char *v = vals[i] ? vals[i] : (isHeader ? "" : p->nullValue);
      int w = widths[i];
      int vl = (int)strlen(v);
      int ra = isRightAlign(p, i, c, isHeader);
