/* ============================================================
** Version override SQL functions
** ============================================================ */
static void fnVersion(sqlite3_context *ctx, int ac, sqlite3_value **av){
  (void)ac; (void)av;
  sqlite3_result_text(ctx, SQLITE_VERSION_OVERRIDE, -1, SQLITE_STATIC);
}
static void fnSourceId(sqlite3_context *ctx, int ac, sqlite3_value **av){
  (void)ac; (void)av;
  sqlite3_result_text(ctx, SQLITE_SOURCE_ID_OVERRIDE, -1, SQLITE_STATIC);
}

static void registerVersionFuncs(sqlite3 *db){
  sqlite3_create_function(db, "sqlite_version", 0, SQLITE_UTF8,
    NULL, fnVersion, NULL, NULL);
  sqlite3_create_function(db, "sqlite_source_id", 0, SQLITE_UTF8,
    NULL, fnSourceId, NULL, NULL);
}

/* ============================================================
** Shell init / open db
** ============================================================ */
static void shellInit(ShellState *p){
  memset(p, 0, sizeof(*p));
  p->out = stdout;
  p->mode = MODE_List;
  strcpy(p->colSep, "|");
  strcpy(p->rowSep, "\n");
  p->nullValue[0] = 0;
  p->showHeader = 0;
  strcpy(p->mainPrompt, "sqlite> ");
  strcpy(p->contPrompt, "   ...> ");
  p->screenWidth = 80;
}

static int openDb(ShellState *p, const char *zFile, int readOnly){
  int flags = readOnly ? SQLITE_OPEN_READONLY :
              (SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE);
  int rc;
  if(p->noFollow) flags |= SQLITE_OPEN_NOFOLLOW;
  if(!zFile) zFile = ":memory:";
  rc = sqlite3_open_v2(zFile, &p->db, flags, NULL);
  if(rc){
    fprintf(stderr, "Error: cannot open %s: %s\n", zFile, sqlite3_errmsg(p->db));
    sqlite3_close(p->db);
    p->db = NULL;
    return rc;
  }
  sqlite3_extended_result_codes(p->db, 1);
  registerVersionFuncs(p->db);
  if(p->progressStep > 0){
    /* progress handler set later */
  }
  return SQLITE_OK;
}

/* ============================================================
** Output helpers
** ============================================================ */
static FILE *outFile(ShellState *p){
  return (p->doOnce && p->outOnce) ? p->outOnce : p->out;
}

static void oputf(ShellState *p, const char *fmt, ...){
  va_list ap;
  FILE *f = outFile(p);
  va_start(ap, fmt);
  vfprintf(f, fmt, ap);
  va_end(ap);
}

static void oputs(ShellState *p, const char *s){
  fputs(s, outFile(p));
}

static void oputc(ShellState *p, int c){
  fputc(c, outFile(p));
}

/* ============================================================
** HTML encoding
** ============================================================ */
static void htmlEsc(FILE *f, const char *z){
  if(!z) return;
  while(*z){
    if(*z=='<' || *z=='>') fputs("&lt;", f);
    else if(*z=='&') fputs("&amp;", f);
    else if(*z=='"') fputs("&quot;", f);
    else fputc(*z, f);
    z++;
  }
}

/* ============================================================
** CSV printing
** ============================================================ */
static void csvPrint(FILE *f, const char *z){
  int needQ = 0;
  const char *s = z;
  if(!z){ return; }
  while(*s){
    if(*s=='"' || *s=='\n' || *s=='\r' || *s==','){needQ=1; break;}
    s++;
  }
  if(!needQ){ fputs(z, f); return; }
  fputc('"', f);
  while(*z){
    if(*z=='"') fputc('"', f);
    fputc(*z, f);
    z++;
  }
  fputc('"', f);
}

/* ============================================================
** Timer
** ============================================================ */
static sqlite3_int64 timeUs(void){
  struct timeval tv;
  gettimeofday(&tv, NULL);
  return (sqlite3_int64)(tv.tv_sec)*1000000 + tv.tv_usec;
}

/* ============================================================
** Progress handler
** ============================================================ */
static int shellProgress(void *pV){
  ShellState *p = (ShellState*)pV;
  p->nProgress++;
  fprintf(stderr, "Progress %d\n", p->nProgress);
  if(seenInterrupt) return 1;
