/* ============================================================
** Print N spaces
** ============================================================ */
static void printSpaces(FILE *f, int n){
  while(n-- > 0) fputc(' ', f);
}

/* ============================================================
** Column mode: compute widths from buffered data
** ============================================================ */
typedef struct ColBuf {
  int   nCol;
  int   nRow;
  int   nAlloc;
  char **azData;    /* nRow * nCol values (NULL = SQL NULL) */
  char **azHeader;  /* nCol headers */
  int  *aType;      /* nCol types (dominant non-null type per col) */
  int  *aPreType;   /* nCol preset type from decltype */
} ColBuf;

static void colBufInit(ColBuf *c){
  memset(c, 0, sizeof(*c));
}

static void colBufFree(ColBuf *c){
  int i;
  for(i=0;i<c->nCol;i++){
    free(c->azHeader[i]);
  }
  free(c->azHeader);
  for(i=0;i<c->nRow*c->nCol;i++) free(c->azData[i]);
  free(c->azData);
  free(c->aType);
  free(c->aPreType);
  memset(c, 0, sizeof(*c));
}

static void colBufAddRow(ColBuf *c, sqlite3_stmt *stmt){
  int i;
  if(c->nRow >= c->nAlloc){
    c->nAlloc = c->nAlloc*2 + 16;
    c->azData = (char**)realloc(c->azData, c->nAlloc*c->nCol*sizeof(char*));
  }
  for(i=0;i<c->nCol;i++){
    int t = sqlite3_column_type(stmt, i);
    const char *v = (const char*)sqlite3_column_text(stmt, i);
    c->azData[c->nRow*c->nCol+i] = (t==SQLITE_NULL) ? NULL : (v ? strdup(v) : strdup(""));
    if(t != SQLITE_NULL && c->aType[i]==SQLITE_NULL) c->aType[i] = t;
    else if(t==SQLITE_FLOAT && c->aType[i]==SQLITE_INTEGER) c->aType[i]=SQLITE_FLOAT;
  }
  c->nRow++;
}

/* ============================================================
** Column widths computation
** ============================================================ */
static void computeWidths(ShellState *p, ColBuf *c, int *wOut){
  int i, j;
  for(i=0;i<c->nCol;i++){
    int w = 0;
    /* From preset */
    if(i < p->nWidth && p->colWidth[i] != 0)
      w = abs(p->colWidth[i]);
    /* From header */
    if(p->showHeader && c->azHeader[i]){
      int h = (int)strlen(c->azHeader[i]);
      if(h > w) w = h;
    }
    /* From data */
    for(j=0;j<c->nRow;j++){
      const char *v = c->azData[j*c->nCol+i];
      int vl = v ? (int)strlen(v) : (int)strlen(p->nullValue);
      if(vl > w) w = vl;
    }
    wOut[i] = w;
  }
}

/* ============================================================
** Is value right-aligned?
** ============================================================ */
static int isRightAlign(ShellState *p, int col, ColBuf *c, int isHeader){
  if(isHeader) return 0;
  int preset = (col < p->nWidth) ? p->colWidth[col] : 0;
  if(preset < 0) return 1;
  int t = c->aType[col];
  return (t==SQLITE_INTEGER || t==SQLITE_FLOAT);
}

/* ============================================================
** Output columnar row
** ============================================================ */
static void outputColRow(ShellState *p, int *widths, ColBuf *c,
                          char **vals, int isHeader, FILE *f){
  int i;
  int nCol = c->nCol;
  if(p->mode == MODE_Column){
    for(i=0;i<nCol;i++){
      const char *v = vals[i] ? vals[i] : (isHeader ? "" : p->nullValue);
      int w = widths[i];
      int vl = (int)strlen(v);
      int ra = isRightAlign(p, i, c, isHeader);
      if(i>0) fputs("  ", f);
      if(ra){
        if(vl < w) printSpaces(f, w-vl);
        fputs(v, f);
      } else {
        fputs(v, f);
        if(i<nCol-1 && vl<w) printSpaces(f, w-vl);
      }
    }
    fputc('\n', f);
  } else if(p->mode == MODE_Table){
    fputs("| ", f);
    for(i=0;i<nCol;i++){
      const char *v = vals[i] ? vals[i] : (isHeader ? "" : p->nullValue);
      int w = widths[i];
      int vl = (int)strlen(v);
      int ra = isRightAlign(p, i, c, isHeader);
      if(ra){ printSpaces(f, w-vl); fputs(v, f); }
      else { fputs(v, f); printSpaces(f, w-vl); }
      fputs(" | ", f);
    }
    fputc('\n', f);
  } else if(p->mode == MODE_Box){
    fputs("\342\224\202 ", f);
    for(i=0;i<nCol;i++){
      const char *v = vals[i] ? vals[i] : (isHeader ? "" : p->nullValue);
      int w = widths[i];
      int vl = (int)strlen(v);
      int ra = isRightAlign(p, i, c, isHeader);
      if(ra){ printSpaces(f, w-vl); fputs(v, f); }
      else { fputs(v, f); printSpaces(f, w-vl); }
      fputs(" \342\224\202 ", f);
    }
    fputc('\n', f);
  } else if(p->mode == MODE_Markdown){
    fputs("| ", f);
    for(i=0;i<nCol;i++){
      const char *v = vals[i] ? vals[i] : (isHeader ? "" : p->nullValue);
      int w = widths[i];
      int vl = (int)strlen(v);
      int ra = isRightAlign(p, i, c, isHeader);
      if(ra){ printSpaces(f, w-vl); fputs(v, f); }
      else { fputs(v, f); printSpaces(f, w-vl); }
      fputs(" | ", f);
    }
    fputc('\n', f);
  }
}

/* ============================================================
** Print table separator line
** ============================================================ */
static void printSepLine(FILE *f, int *widths, int nCol,
                          const char *l, const char *m, const char *r,
                          const char *fill){
  int i,j;
  fputs(l, f);
  for(i=0;i<nCol;i++){
    for(j=0;j<widths[i]+2;j++) fputs(fill, f);
    if(i<nCol-1) fputs(m, f);
  }
  fputs(r, f);
  fputc('\n', f);
}

/* ============================================================
** Flush buffered column mode output
** ============================================================ */
static void flushColBuf(ShellState *p, ColBuf *c){
  FILE *f = outFile(p);
  int *widths;
  int i, j;
  int nCol = c->nCol;
  if(nCol <= 0) return;
  widths = (int*)malloc(nCol*sizeof(int));
  computeWidths(p, c, widths);

  if(p->mode == MODE_Column){
    if(p->showHeader && c->azHeader){
      outputColRow(p, widths, c, c->azHeader, 1, f);
      for(i=0;i<nCol;i++){
        if(i>0) fputs("  ", f);
        for(j=0;j<widths[i];j++) fputc('-', f);
      }
      fputc('\n', f);
    }
    for(j=0;j<c->nRow;j++)
      outputColRow(p, widths, c, c->azData+j*nCol, 0, f);

  } else if(p->mode == MODE_Table){
    printSepLine(f, widths, nCol, "+", "+", "+", "-");
    if(p->showHeader && c->azHeader){
      outputColRow(p, widths, c, c->azHeader, 1, f);
      printSepLine(f, widths, nCol, "+", "+", "+", "-");
    }
    for(j=0;j<c->nRow;j++)
      outputColRow(p, widths, c, c->azData+j*nCol, 0, f);
    printSepLine(f, widths, nCol, "+", "+", "+", "-");

  } else if(p->mode == MODE_Box){
    /* top: ╭──┬──╮ */
    fputs("\342\225\255", f);
    for(i=0;i<nCol;i++){
      for(j=0;j<widths[i]+2;j++) fputs("\342\224\200", f);
      if(i<nCol-1) fputs("\342\224\254", f);
    }
    fputs("\342\225\256\n", f);
    if(p->showHeader && c->azHeader){
      outputColRow(p, widths, c, c->azHeader, 1, f);
      /* ╞══╪══╡ */
      fputs("\342\225\236", f);
      for(i=0;i<nCol;i++){
        for(j=0;j<widths[i]+2;j++) fputs("\342\225\220", f);
        if(i<nCol-1) fputs("\342\225\252", f);
      }
      fputs("\342\225\241\n", f);
    }
    for(j=0;j<c->nRow;j++)
      outputColRow(p, widths, c, c->azData+j*nCol, 0, f);
    /* bottom: ╰──┴──╯ */
    fputs("\342\225\260", f);
    for(i=0;i<nCol;i++){
      for(j=0;j<widths[i]+2;j++) fputs("\342\224\200", f);
      if(i<nCol-1) fputs("\342\224\264", f);
    }
    fputs("\342\225\257\n", f);

  } else if(p->mode == MODE_Markdown){
    if(p->showHeader && c->azHeader){
      outputColRow(p, widths, c, c->azHeader, 1, f);
      fputs("|", f);
      for(i=0;i<nCol;i++){
        for(j=0;j<widths[i]+2;j++) fputc('-', f);
        fputc('|', f);
      }
      fputc('\n', f);
    }
    for(j=0;j<c->nRow;j++)
      outputColRow(p, widths, c, c->azData+j*nCol, 0, f);
  }
  free(widths);
}

