/* ============================================================
** JSON output helpers
** ============================================================ */
static void jsonStr(FILE *f, const char *z){
  fputc('"', f);
  if(z) while(*z){
    unsigned char c = (unsigned char)*z;
    if(c=='"') fputs("\\\"", f);
    else if(c=='\\') fputs("\\\\", f);
    else if(c=='\n') fputs("\\n", f);
    else if(c=='\r') fputs("\\r", f);
    else if(c=='\t') fputs("\\t", f);
    else if(c<0x20) fprintf(f, "\\u%04x", c);
    else fputc(c, f);
    z++;
  }
  fputc('"', f);
}

static void jsonDouble(FILE *f, double d){
  char buf[64];
  if(d != d || d*0.0 != 0.0){ fputs("null", f); return; }
  snprintf(buf, sizeof(buf), "%.15g", d);
  fputs(buf, f);
}

/* ============================================================
** Bind parameters to a prepared statement
** ============================================================ */
static void bindParams(ShellState *p, sqlite3_stmt *stmt){
  int i, n;
  n = sqlite3_bind_parameter_count(stmt);
  for(i=1;i<=n;i++){
    const char *name = sqlite3_bind_parameter_name(stmt, i);
    int j;
    if(!name) continue;
    for(j=0;j<p->nParam;j++){
      if(strcmp(p->aParam[j].zName, name)==0){
        const char *v = p->aParam[j].zValue;
        if(v==NULL || strcmp(v,"NULL")==0)
          sqlite3_bind_null(stmt, i);
        else
          sqlite3_bind_text(stmt, i, v, -1, SQLITE_STATIC);
        break;
      }
    }
  }
}

/* ============================================================
** Check if SQL is EXPLAIN or EXPLAIN QUERY PLAN
** ============================================================ */
static int sqlIsExplain(const char *z){
  while(*z && isspace((unsigned char)*z)) z++;
  return (ci_ncmp(z, "EXPLAIN", 7)==0);
}

static int ci_ncmp(const char *a, const char *b, int n){
  while(n-- > 0){
    int ca = tolower((unsigned char)*a++);
    int cb = tolower((unsigned char)*b++);
    if(ca != cb) return ca-cb;
    if(ca==0) return 0;
  }
  return 0;
}

/* ============================================================
** EQP tree rendering
** ============================================================ */
static void eqpClear(EQPGraph *g){
  EQPGraphRow *p = g->pRow;
  while(p){ EQPGraphRow *next=p->pNext; free(p); p=next; }
  g->pRow = g->pLast = NULL;
}

static void eqpAddRow(EQPGraph *g, int id, int pid, const char *zText){
  EQPGraphRow *r = (EQPGraphRow*)malloc(sizeof(EQPGraphRow));
  r->iEqpId = id;
  r->iParentId = pid;
  strncpy(r->zText, zText ? zText : "", sizeof(r->zText)-1);
  r->zText[sizeof(r->zText)-1] = 0;
  r->pNext = NULL;
  if(g->pLast) g->pLast->pNext = r;
  else g->pRow = r;
  g->pLast = r;
}

static void eqpRenderLevel(EQPGraph *g, FILE *f, int pid, const char *prefix){
  EQPGraphRow *r;
  /* Count children of pid */
  int count = 0;
  for(r=g->pRow; r; r=r->pNext){
    if(r->iParentId==pid) count++;
  }
  int idx = 0;
  for(r=g->pRow; r; r=r->pNext){
    if(r->iParentId != pid) continue;
    idx++;
    int isLast = (idx==count);
    const char *branch = isLast ? "`--" : "|--";
    fprintf(f, "%s%s%s\n", prefix, branch, r->zText);
    char newPrefix[200];
    snprintf(newPrefix, sizeof(newPrefix), "%s%s",
             prefix, isLast ? "   " : "|  ");
    eqpRenderLevel(g, f, r->iEqpId, newPrefix);
  }
}

static void eqpRender(EQPGraph *g, FILE *f){
  fputs("QUERY PLAN\n", f);
  eqpRenderLevel(g, f, 0, "");
}

/* ============================================================
** Main SQL execution function
** ============================================================ */
static int runOneSql(ShellState *p, const char *zSql);
static int runSql(ShellState *p, const char *zSql);

static int runOneSql(ShellState *p, const char *zSql){
  sqlite3_stmt *stmt = NULL;
  const char *zTail = NULL;
  int rc;
  FILE *f = outFile(p);
  sqlite3_int64 tStart = 0;

  if(p->doTimer) tStart = timeUs();

  rc = sqlite3_prepare_v2(p->db, zSql, -1, &stmt, &zTail);
  if(rc != SQLITE_OK){
    return rc;
  }
  if(!stmt){ return SQLITE_OK; }

  bindParams(p, stmt);

  int nCol = sqlite3_column_count(stmt);
  int isEQP = 0;  /* Is this an EXPLAIN QUERY PLAN? */
  int isExplain = 0; /* Is this an EXPLAIN? */

  /* Check if it's EXPLAIN */
  {
    const char *z = zSql;
    while(*z && isspace((unsigned char)*z)) z++;
    if(ci_ncmp(z,"EXPLAIN",7)==0){
      z+=7;
      while(*z && isspace((unsigned char)*z)) z++;
      if(ci_ncmp(z,"QUERY",5)==0){
        isEQP = 1;
      } else {
        isExplain = 1;
      }
    }
  }

  if(p->eqpOn && !isEQP && !isExplain){
    /* Run EXPLAIN QUERY PLAN first */
    char *zEQP = sqlite3_mprintf("EXPLAIN QUERY PLAN %s", zSql);
    sqlite3_stmt *eqpStmt = NULL;
    if(sqlite3_prepare_v2(p->db, zEQP, -1, &eqpStmt, NULL)==SQLITE_OK && eqpStmt){
      eqpClear(&p->eqpGraph);
      while(sqlite3_step(eqpStmt)==SQLITE_ROW){
        int id = sqlite3_column_int(eqpStmt, 0);
        int pid = sqlite3_column_int(eqpStmt, 1);
        const char *txt = (const char*)sqlite3_column_text(eqpStmt, 3);
        eqpAddRow(&p->eqpGraph, id, pid, txt);
      }
      sqlite3_finalize(eqpStmt);
      eqpRender(&p->eqpGraph, f);
      eqpClear(&p->eqpGraph);
    }
    sqlite3_free(zEQP);
    if(p->eqpOn >= 2){
      /* Full EQP: also show EXPLAIN output */
      char *zExp = sqlite3_mprintf("EXPLAIN %s", zSql);
      sqlite3_stmt *expStmt = NULL;
      if(sqlite3_prepare_v2(p->db, zExp, -1, &expStmt, NULL)==SQLITE_OK && expStmt){
        /* Print explain output in explain format */
        int ec = sqlite3_column_count(expStmt);
        /* Print header */
        {
          static const int expWidths[] = {4,13,4,4,4,13,2,13};
          static const char *expHdr[] = {"addr","opcode","p1","p2","p3","p4","p5","comment"};
          for(int ei=0;ei<8;ei++){
            if(ei>0) fputs("  ",f);
            fprintf(f, "%-*s", expWidths[ei], expHdr[ei]);
          }
          fputc('\n', f);
          for(int ei=0;ei<8;ei++){
            if(ei>0) fputs("  ",f);
            for(int ej=0;ej<expWidths[ei];ej++) fputc('-',f);
          }
          fputc('\n', f);
        }
        while(sqlite3_step(expStmt)==SQLITE_ROW){
          static const int expWidths[] = {4,13,4,4,4,13,2,13};
          for(int ei=0;ei<(ec<8?ec:8);ei++){
            const char *v = (const char*)sqlite3_column_text(expStmt,ei);
            if(!v) v="";
            if(ei>0) fputs("  ",f);
            int t = sqlite3_column_type(expStmt,ei);
            if(t==SQLITE_INTEGER || t==SQLITE_FLOAT){
              fprintf(f, "%*s", expWidths[ei], v);
            } else {
              fprintf(f, "%-*s", expWidths[ei], v);
            }
          }
          fputc('\n', f);
        }
        sqlite3_finalize(expStmt);
      }
      sqlite3_free(zExp);
    }
  }

  if(isEQP){
    /* Render EQP tree */
    eqpClear(&p->eqpGraph);
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      int id = sqlite3_column_int(stmt, 0);
      int pid = sqlite3_column_int(stmt, 1);
      const char *txt = (const char*)sqlite3_column_text(stmt, 3);
      eqpAddRow(&p->eqpGraph, id, pid, txt);
    }
    eqpRender(&p->eqpGraph, f);
    eqpClear(&p->eqpGraph);
    sqlite3_finalize(stmt);
    if(p->doTimer) goto timer_done;
    return SQLITE_OK;
  }

  if(isExplain || sqlite3_stmt_isexplain(stmt)){
    /* EXPLAIN output: fixed-width columns */
    static const int expW[] = {4,13,4,4,4,13,2,13};
    static const char *expH[] = {"addr","opcode","p1","p2","p3","p4","p5","comment"};
    int ne = 8;
    /* header */
    for(int ei=0;ei<ne;ei++){
      if(ei>0) fputs("  ",f);
      fprintf(f, "%-*s", expW[ei], expH[ei]);
    }
    fputc('\n',f);
    for(int ei=0;ei<ne;ei++){
      if(ei>0) fputs("  ",f);
      for(int ej=0;ej<expW[ei];ej++) fputc('-',f);
    }
    fputc('\n',f);
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      for(int ei=0;ei<ne && ei<nCol;ei++){
        const char *v = (const char*)sqlite3_column_text(stmt,ei);
        if(!v) v="";
        if(ei>0) fputs("  ",f);
        int t2 = sqlite3_column_type(stmt,ei);
        if(t2==SQLITE_INTEGER){
          fprintf(f, "%*s", expW[ei], v);
        } else {
          fprintf(f, "%-*s", expW[ei], v);
        }
      }
      fputc('\n',f);
    }
    sqlite3_finalize(stmt);
    if(p->doTimer) goto timer_done;
    return SQLITE_OK;
  }

  /* Buffered modes: column, table, box, markdown */
  if(p->mode==MODE_Column || p->mode==MODE_Table ||
     p->mode==MODE_Box || p->mode==MODE_Markdown){
    ColBuf cb;
    colBufInit(&cb);
    cb.nCol = nCol;
    cb.azHeader = (char**)calloc(nCol, sizeof(char*));
    cb.aType = (int*)calloc(nCol, sizeof(int));
    cb.aPreType = (int*)calloc(nCol, sizeof(int));
    for(int i=0;i<nCol;i++){
      const char *h = sqlite3_column_name(stmt,i);
      cb.azHeader[i] = h ? strdup(h) : strdup("");
      cb.aType[i] = SQLITE_NULL;
    }
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      colBufAddRow(&cb, stmt);
    }
    flushColBuf(p, &cb);
    colBufFree(&cb);
    sqlite3_finalize(stmt);
    if(rc==SQLITE_DONE) rc=SQLITE_OK;
    if(p->doTimer) goto timer_done;
    return rc;
  }

  /* JSON mode */
  if(p->mode==MODE_Json){
    char **colNames = (char**)malloc(nCol*sizeof(char*));
    for(int i=0;i<nCol;i++){
      const char *h = sqlite3_column_name(stmt,i);
      colNames[i] = h ? strdup(h) : strdup("");
    }
    int first=1;
    fputs("[", f);
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      if(!first) fputs(",\n",f); else first=0;
      fputs("{",f);
      for(int i=0;i<nCol;i++){
        if(i>0) fputc(',',f);
        jsonStr(f, colNames[i]);
        fputc(':',f);
        int t = sqlite3_column_type(stmt,i);
        if(t==SQLITE_NULL) fputs("null",f);
        else if(t==SQLITE_INTEGER)
          fprintf(f, "%lld", (long long)sqlite3_column_int64(stmt,i));
        else if(t==SQLITE_FLOAT)
          jsonDouble(f, sqlite3_column_double(stmt,i));
        else if(t==SQLITE_BLOB){
          int nb=sqlite3_column_bytes(stmt,i);
          const unsigned char *zb=(const unsigned char*)sqlite3_column_blob(stmt,i);
          fputc('"',f);
          for(int bi=0;bi<nb;bi++) fprintf(f,"\\u%04x",zb[bi]);
          fputc('"',f);
        } else {
          jsonStr(f, (const char*)sqlite3_column_text(stmt,i));
        }
      }
      fputs("}",f);
    }
    fputs("]\n",f);
    for(int i=0;i<nCol;i++) free(colNames[i]);
    free(colNames);
    sqlite3_finalize(stmt);
    if(rc==SQLITE_DONE) rc=SQLITE_OK;
    if(p->doTimer) goto timer_done;
    return rc;
  }

  /* HTML mode */
  if(p->mode==MODE_Html){
    if(p->showHeader && nCol>0){
      fputs("<TR>\n",f);
      for(int i=0;i<nCol;i++){
        const char *h=sqlite3_column_name(stmt,i);
        fputs("<TH>",f); htmlEsc(f,h?h:""); fputc('\n',f);
      }
      fputs("</TR>\n",f);
    }
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      fputs("<TR>\n",f);
      for(int i=0;i<nCol;i++){
        int t=sqlite3_column_type(stmt,i);
        const char *v=(t==SQLITE_NULL)?p->nullValue:(const char*)sqlite3_column_text(stmt,i);
        fputs("<TD>",f); htmlEsc(f,v?v:""); fputc('\n',f);
      }
      fputs("</TR>\n",f);
    }
    sqlite3_finalize(stmt);
    if(rc==SQLITE_DONE) rc=SQLITE_OK;
    if(p->doTimer) goto timer_done;
    return rc;
  }

  /* Line mode */
  if(p->mode==MODE_Line){
    /* Compute max name width */
    int maxw=0;
    for(int i=0;i<nCol;i++){
      const char *h=sqlite3_column_name(stmt,i);
      int hlen=h?(int)strlen(h):0;
      if(hlen>maxw) maxw=hlen;
    }
    int first=1;
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      if(!first) fputc('\n',f); else first=0;
      for(int i=0;i<nCol;i++){
        const char *h=sqlite3_column_name(stmt,i);
        int hlen=h?(int)strlen(h):0;
        int t=sqlite3_column_type(stmt,i);
        const char *v=(t==SQLITE_NULL)?p->nullValue:(const char*)sqlite3_column_text(stmt,i);
        printSpaces(f, maxw-hlen);
        fprintf(f, "%s: %s\n", h?h:"", v?v:"");
      }
    }
    sqlite3_finalize(stmt);
    if(rc==SQLITE_DONE) rc=SQLITE_OK;
    if(p->doTimer) goto timer_done;
    return rc;
  }

  /* Insert mode */
  if(p->mode==MODE_Insert){
    const char *tbl = p->zInsertTable[0] ? p->zInsertTable : "tab";
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      fprintf(f, "INSERT INTO %s VALUES(", tbl);
      for(int i=0;i<nCol;i++){
        if(i>0) fputc(',',f);
        int t=sqlite3_column_type(stmt,i);
        if(t==SQLITE_NULL) fputs("NULL",f);
        else if(t==SQLITE_INTEGER)
          fprintf(f,"%lld",(long long)sqlite3_column_int64(stmt,i));
        else if(t==SQLITE_FLOAT){
          char buf[64];
          snprintf(buf,sizeof(buf),"%.15g",sqlite3_column_double(stmt,i));
          fputs(buf,f);
        } else if(t==SQLITE_BLOB){
          int nb=sqlite3_column_bytes(stmt,i);
          const unsigned char *zb=(const unsigned char*)sqlite3_column_blob(stmt,i);
          fputs("X'",f);
          for(int bi=0;bi<nb;bi++) fprintf(f,"%02X",zb[bi]);
          fputc('\'',f);
        } else {
          const char *v=(const char*)sqlite3_column_text(stmt,i);
          fputc('\'',f);
          if(v) while(*v){ if(*v=='\'') fputc('\'',f); fputc(*v,f); v++; }
          fputc('\'',f);
        }
      }
      fputs(");\n",f);
    }
    sqlite3_finalize(stmt);
    if(rc==SQLITE_DONE) rc=SQLITE_OK;
    if(p->doTimer) goto timer_done;
    return rc;
  }

  /* All other modes: List, CSV, Quote, Tabs, TCL, ASCII */
  if(p->showHeader && nCol>0){
    if(p->mode==MODE_Csv){
      for(int i=0;i<nCol;i++){
        if(i>0) fputc(',',f);
        const char *h=sqlite3_column_name(stmt,i);
        csvPrint(f, h?h:"");
      }
      fputs("\r\n",f);
    } else if(p->mode==MODE_Tcl){
      for(int i=0;i<nCol;i++){
        if(i>0) fputc(' ',f);
        const char *h=sqlite3_column_name(stmt,i);
        fputc('"',f); fputs(h?h:"",f); fputc('"',f);
      }
      fputc('\n',f);
    } else {
      for(int i=0;i<nCol;i++){
        if(i>0) fputs(p->colSep,f);
        const char *h=sqlite3_column_name(stmt,i);
        fputs(h?h:"",f);
      }
      fputs(p->rowSep,f);
    }
  }

  while((rc=sqlite3_step(stmt))==SQLITE_ROW){
    for(int i=0;i<nCol;i++){
      int t=sqlite3_column_type(stmt,i);
      const char *v=(t==SQLITE_NULL)?NULL:(const char*)sqlite3_column_text(stmt,i);
      const char *nv = v ? v : p->nullValue;

      if(p->mode==MODE_List){
        if(i>0) fputs(p->colSep,f);
        fputs(nv,f);
        if(i==nCol-1) fputs(p->rowSep,f);
      } else if(p->mode==MODE_Csv){
        if(i>0) fputc(',',f);
        if(v) csvPrint(f,v); /* NULL -> empty */
        if(i==nCol-1) fputs("\r\n",f);
      } else if(p->mode==MODE_Tabs){
        if(i>0) fputc('\t',f);
        fputs(nv,f);
        if(i==nCol-1) fputc('\n',f);
      } else if(p->mode==MODE_Quote){
        if(i>0) fputc(',',f);
        if(t==SQLITE_NULL) fputs("NULL",f);
        else if(t==SQLITE_INTEGER)
          fprintf(f,"%lld",(long long)sqlite3_column_int64(stmt,i));
        else if(t==SQLITE_FLOAT){
          char buf[64]; snprintf(buf,sizeof(buf),"%.15g",sqlite3_column_double(stmt,i));
          fputs(buf,f);
        } else if(t==SQLITE_BLOB){
          int nb=sqlite3_column_bytes(stmt,i);
          const unsigned char *zb=(const unsigned char*)sqlite3_column_blob(stmt,i);
          fputs("X'",f);
          for(int bi=0;bi<nb;bi++) fprintf(f,"%02X",zb[bi]);
          fputc('\'',f);
        } else {
          fputc('\'',f);
          if(v) while(*v){if(*v=='\'')fputc('\'',f);fputc(*v,f);v++;}
          fputc('\'',f);
        }
        if(i==nCol-1) fputc('\n',f);
      } else if(p->mode==MODE_Ascii){
        if(i>0) fputc(0x1F,f);
        fputs(nv,f);
        if(i==nCol-1) fputc(0x1E,f);
      } else if(p->mode==MODE_Tcl){
        if(i>0) fputc(' ',f);
        /* TCL list element quoting */
        if(!v || !v[0]){
          fputs("\"\"",f);
        } else {
          int needQ=0;
          const char *s=v;
          while(*s){
            if(*s==' '||*s=='\t'||*s=='\n'||*s=='"'||*s=='{'||*s=='}'||*s=='['||*s==']'||*s=='\\'){
              needQ=1; break;
            }
            s++;
          }
          if(needQ){
            fputc('"',f);
            while(*v){
              if(*v=='"'||*v=='\\'||*v=='['||*v==']') fputc('\\',f);
              fputc(*v,f); v++;
            }
            fputc('"',f);
          } else {
            fputs(v,f);
          }
        }
        if(i==nCol-1) fputc('\n',f);
      }
    }
  }

  sqlite3_finalize(stmt);
  if(rc==SQLITE_DONE) rc=SQLITE_OK;

timer_done:
  if(p->doTimer && tStart>0){
    sqlite3_int64 tEnd=timeUs();
    double real=(tEnd-tStart)/1000000.0;
    struct rusage ru;
    double user=0.0, sys=0.0;
#ifdef RUSAGE_SELF
    if(getrusage(RUSAGE_SELF,&ru)==0){
      user = ru.ru_utime.tv_sec + ru.ru_utime.tv_usec/1e6;
      sys  = ru.ru_stime.tv_sec + ru.ru_stime.tv_usec/1e6;
    }
#endif
    fprintf(stderr,"Run Time: real %.6f user %.6f sys %.6f\n", real, user, sys);
  }
  return rc;
}

