  sqlite3_status64(SQLITE_STATUS_MEMORY_USED, &iCur64, &iHi64, 0);
  fprintf(f,"Memory Used:                         %lld (max %lld) bytes\n",
          (long long)iCur64, (long long)iHi64);
  sqlite3_status(SQLITE_STATUS_MALLOC_COUNT, &iCur, &iHi, 0);
  fprintf(f,"Number of Outstanding Allocations:   %d (max %d)\n", iCur, iHi);
  sqlite3_status64(SQLITE_STATUS_PAGECACHE_OVERFLOW, &iCur64, &iHi64, 0);
  fprintf(f,"Number of Pcache Overflow Bytes:     %lld (max %lld) bytes\n",
          (long long)iCur64, (long long)iHi64);
  sqlite3_status(SQLITE_STATUS_MALLOC_SIZE, &iCur, &iHi, 0);
  fprintf(f,"Largest Allocation:                  %d bytes\n", iHi);
  sqlite3_status(SQLITE_STATUS_PAGECACHE_USED, &iCur, &iHi, 0);
  /* skip pagecache size stat */
  /* Lookaside from db_status */
  if(p->db){
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_LOOKASIDE_USED, &iCur, &iHi, 0);
    fprintf(f,"Lookaside Slots Used:                %d (max %d)\n", iCur, iHi);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_LOOKASIDE_HIT, &iCur, &iHi, 0);
    fprintf(f,"Successful lookaside attempts:       %d\n", iHi);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_LOOKASIDE_MISS_SIZE, &iCur, &iHi, 0);
    fprintf(f,"Lookaside failures due to size:      %d\n", iHi);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_LOOKASIDE_MISS_FULL, &iCur, &iHi, 0);
    fprintf(f,"Lookaside failures due to OOM:       %d\n", iHi);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_CACHE_USED, &iCur, &iHi, 0);
    fprintf(f,"Pager Heap Usage:                    %d bytes\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_CACHE_HIT, &iCur, &iHi, 1);
    fprintf(f,"Page cache hits:                     %d\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_CACHE_MISS, &iCur, &iHi, 1);
    fprintf(f,"Page cache misses:                   %d\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_CACHE_WRITE, &iCur, &iHi, 1);
    fprintf(f,"Page cache writes:                   %d\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_CACHE_SPILL, &iCur, &iHi, 1);
    fprintf(f,"Page cache spills:                   %d\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_DEFERRED_FKS, &iCur, &iHi, 0);
    fprintf(f,"Temporary data spilled to disk:      %d\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_SCHEMA_USED, &iCur, &iHi, 0);
    fprintf(f,"Schema Heap Usage:                   %d bytes\n", iCur);
    sqlite3_db_status(p->db, SQLITE_DBSTATUS_STMT_USED, &iCur, &iHi, 0);
    fprintf(f,"Statement Heap/Lookaside Usage:      %d bytes\n", iCur);
  }
  if(pStmt){
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_FULLSCAN_STEP, 0);
    fprintf(f,"Fullscan Steps:                      %d\n", iCur);
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_SORT, 0);
    fprintf(f,"Sort Operations:                     %d\n", iCur);
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_AUTOINDEX, 0);
    fprintf(f,"Autoindex Inserts:                   %d\n", iCur);
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_VM_STEP, 0);
    fprintf(f,"Virtual Machine Steps:               %d\n", iCur);
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_REPREPARE, 0);
    fprintf(f,"Reprepare operations:                %d\n", iCur);
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_RUN, 0);
    fprintf(f,"Number of times run:                 %d\n", iCur);
    iCur = sqlite3_stmt_status(pStmt, SQLITE_STMTSTATUS_MEMUSED, 0);
    fprintf(f,"Memory used by prepared stmt:        %d\n", iCur);
  }
}

/* ============================================================
** Tokenize shell input into a argv array
** ============================================================ */
static int tokenize(const char *zLine, char ***pazArgs){
  int nArg=0, nAlloc=8;
  char **az = (char**)malloc(nAlloc*sizeof(char*));
  const char *z = zLine;

  while(*z && *z!='\n'){
    while(*z && isspace((unsigned char)*z) && *z!='\n') z++;
    if(!*z || *z=='\n') break;

    char buf[4096];
    int n=0;

    if(*z=='"' || *z=='\''){
      char q = *z++;
      while(*z && *z!=q){
        if(*z=='\\' && *(z+1)){
          z++;
          switch(*z){
            case 'n': buf[n++]='\n'; break;
            case 't': buf[n++]='\t'; break;
            case 'r': buf[n++]='\r'; break;
            default: buf[n++]=*z; break;
          }
        } else {
          buf[n++]=*z;
        }
        z++;
      }
      if(*z==q) z++;
    } else {
      while(*z && !isspace((unsigned char)*z) && *z!='\n'){
        buf[n++]=*z++;
      }
    }
    buf[n]=0;

    if(nArg>=nAlloc){
      nAlloc*=2;
      az=(char**)realloc(az, nAlloc*sizeof(char*));
    }
    az[nArg++]=strdup(buf);
  }
  *pazArgs = az;
  return nArg;
}

static void freeArgs(char **az, int n){
  int i;
  for(i=0;i<n;i++) free(az[i]);
  free(az);
}

/* ============================================================
** .tables formatting
** ============================================================ */
static void printTableList(ShellState *p, char **az, int n){
  FILE *f = outFile(p);
  if(n==0) return;
  /* Find max name length */
  int maxLen=0;
  for(int i=0;i<n;i++){
    int l = (int)strlen(az[i]);
    if(l>maxLen) maxLen=l;
  }
  int colW = maxLen + 2;
  int sw = p->screenWidth > 0 ? p->screenWidth : 80;
  int nPerRow = sw / colW;
  if(nPerRow<1) nPerRow=1;
  int nRows = (n + nPerRow - 1) / nPerRow;

  for(int row=0; row<nRows; row++){
    for(int col=0; col<nPerRow; col++){
      int idx = col*nRows + row;
      if(idx>=n) break;
      fprintf(f, "%-*s", colW, az[idx]);
    }
    /* Trim trailing spaces */
    fputc('\n', f);
  }
}

/* ============================================================
** Import CSV/text data
** ============================================================ */
typedef struct ImportCtx {
  const char *zFile;
  FILE *fp;
  char *z;
  int n;
  int sz;
  int eol;
  const char *zDataSep;
  int mode; /* 0=csv, 1=other */
  int nLine;
  int bHdr;
  int nSkip;
} ImportCtx;

static void importGrow(ImportCtx *c, int n){
  if(c->n+n+1 > c->sz){
    c->sz = c->sz*2+n+64;
    c->z = (char*)realloc(c->z, c->sz);
  }
}

/* Read one CSV field. Returns pointer to field, sets *pEOL=1 at line end */
static char *csvField(ImportCtx *c, int *pEOL){
  int ch;
  c->n = 0;
  *pEOL = 0;

  if(c->mode==0){ /* CSV */
    ch = fgetc(c->fp);
    if(ch==EOF){ *pEOL=1; return NULL; }

    if(ch=='"'){
      /* Quoted field */
      while(1){
        ch=fgetc(c->fp);
        if(ch==EOF){ break; }
        if(ch=='"'){
          int ch2=fgetc(c->fp);
          if(ch2=='"'){ importGrow(c,2); c->z[c->n++]='"'; }
          else {
            /* End of quoted field */
            if(ch2=='\n'||ch2==EOF) *pEOL=1;
            else if(ch2=='\r'){
              int ch3=fgetc(c->fp);
              if(ch3!='\n') ungetc(ch3,c->fp);
              *pEOL=1;
            }
            /* ch2 is ',' or EOL */
            break;
          }
        } else if(ch=='\n'){
          importGrow(c,2); c->z[c->n++]='\n';
        } else if(ch=='\r'){
          int ch2=fgetc(c->fp);
          if(ch2!='\n') ungetc(ch2,c->fp);
          importGrow(c,2); c->z[c->n++]='\n';
        } else {
          importGrow(c,2); c->z[c->n++]=(char)ch;
        }
      }
    } else {
      /* Unquoted field */
      while(ch!=',' && ch!='\n' && ch!='\r' && ch!=EOF){
        importGrow(c,2); c->z[c->n++]=(char)ch;
        ch=fgetc(c->fp);
      }
      if(ch=='\n') *pEOL=1;
      else if(ch=='\r'){
        *pEOL=1;
        int ch2=fgetc(c->fp);
        if(ch2!='\n') ungetc(ch2,c->fp);
      } else if(ch==EOF) *pEOL=1;
    }
  } else {
    /* Separated by zDataSep */
    int sepLen = (int)strlen(c->zDataSep);
    while(1){
      ch=fgetc(c->fp);
      if(ch==EOF){ *pEOL=1; break; }
      if(ch=='\n'){ *pEOL=1; c->nLine++; break; }
      if(ch=='\r'){
        int ch2=fgetc(c->fp);
        if(ch2!='\n') ungetc(ch2,c->fp);
        *pEOL=1; c->nLine++; break;
      }
      importGrow(c,2); c->z[c->n++]=(char)ch;
      /* Check for separator */
      if(c->n >= sepLen &&
         memcmp(c->z+c->n-sepLen, c->zDataSep, sepLen)==0){
        c->n -= sepLen;
        break;
      }
    }
  }

  importGrow(c, 1);
  c->z[c->n] = 0;
  return c->z;
}

/* ============================================================
** Clone a database
** ============================================================ */
static int doClone(ShellState *p, const char *zNewDb){
  /* Get list of tables */
  sqlite3 *pNew = NULL;
  int rc;
  char *zErr = NULL;

  rc = sqlite3_open_v2(zNewDb, &pNew,
       SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE, NULL);
  if(rc){
    fprintf(stderr, "Error: cannot open %s\n", zNewDb);
    return rc;
  }
  registerVersionFuncs(pNew);

  /* Get list of tables from old db */
  sqlite3_stmt *stmt = NULL;
  rc = sqlite3_prepare_v2(p->db,
    "SELECT name, sql FROM sqlite_master WHERE type='table' ORDER BY rowid",
    -1, &stmt, NULL);
  if(rc) { sqlite3_close(pNew); return rc; }

  while(sqlite3_step(stmt)==SQLITE_ROW){
    const char *name = (const char*)sqlite3_column_text(stmt, 0);
    const char *sql  = (const char*)sqlite3_column_text(stmt, 1);
    if(!name || !sql) continue;
    fprintf(outFile(p), "%s...", name);
    fflush(outFile(p));

    /* Create table in new db */
    sqlite3_exec(pNew, sql, NULL, NULL, &zErr);
    if(zErr){ sqlite3_free(zErr); zErr=NULL; }

    /* Copy data */
    char *zSel = sqlite3_mprintf("SELECT * FROM \"%w\"", name);
    sqlite3_stmt *sel=NULL;
    if(sqlite3_prepare_v2(p->db, zSel, -1, &sel, NULL)==SQLITE_OK){
      int nc = sqlite3_column_count(sel);
      while(sqlite3_step(sel)==SQLITE_ROW){
        /* Build INSERT */
        StrBuf sb; sb_init(&sb);
        sb_appendf(&sb, "INSERT INTO \"%s\" VALUES(", name);
        for(int i=0;i<nc;i++){
          if(i>0) sb_append(&sb, ",");
          int t=sqlite3_column_type(sel,i);
          if(t==SQLITE_NULL) sb_append(&sb,"NULL");
          else if(t==SQLITE_INTEGER){
            char buf[32];
            snprintf(buf,sizeof(buf),"%lld",(long long)sqlite3_column_int64(sel,i));
            sb_append(&sb,buf);
          } else if(t==SQLITE_FLOAT){
            char buf[64];
            snprintf(buf,sizeof(buf),"%.15g",sqlite3_column_double(sel,i));
            sb_append(&sb,buf);
          } else {
            const char *v=(const char*)sqlite3_column_text(sel,i);
            sb_append(&sb,"'");
            if(v) while(*v){
              if(*v=='\'') sb_append(&sb,"'");
              char cc[2]={*v,0};
              sb_append(&sb,cc);
              v++;
            }
            sb_append(&sb,"'");
          }
        }
        sb_append(&sb,")");
        sqlite3_exec(pNew, sb.z, NULL, NULL, &zErr);
        if(zErr){sqlite3_free(zErr);zErr=NULL;}
        sb_free(&sb);
      }
      sqlite3_finalize(sel);
    }
    sqlite3_free(zSel);
    fprintf(outFile(p), " done\n");
  }
  sqlite3_finalize(stmt);

  /* Copy indexes, views, triggers */
  rc = sqlite3_prepare_v2(p->db,
    "SELECT sql FROM sqlite_master WHERE type!='table' AND sql NOT NULL ORDER BY rowid",
    -1, &stmt, NULL);
  if(rc==SQLITE_OK){
    while(sqlite3_step(stmt)==SQLITE_ROW){
      const char *sql=(const char*)sqlite3_column_text(stmt,0);
      if(sql) sqlite3_exec(pNew, sql, NULL, NULL, &zErr);
      if(zErr){sqlite3_free(zErr);zErr=NULL;}
    }
    sqlite3_finalize(stmt);
  }

  sqlite3_close(pNew);
  return SQLITE_OK;
}

