/* ============================================================
** Run multiple SQL statements
** ============================================================ */
static int runSql(ShellState *p, const char *zSql){
  const char *z = zSql;
  int rc = SQLITE_OK;

  while(z && *z){
    const char *zNext = NULL;
    sqlite3_stmt *temp = NULL;

    /* Find the end of this statement */
    int rc2 = sqlite3_prepare_v2(p->db, z, -1, &temp, &zNext);
    if(rc2 != SQLITE_OK){
      fprintf(stderr, "Parse error near line %d: %s\n",
              p->lineno, sqlite3_errmsg(p->db));
      /* Try to find error offset for pointer */
      const char *zErr = z;
      /* Show the original SQL and error pointer */
      fprintf(stderr, "  %s\n", z);
      fprintf(stderr, "  ^--- error here\n");
      p->nErr++;
      if(p->bail) return rc2;
      /* Skip to next statement */
      while(*z && *z!=';') z++;
      if(*z==';') z++;
      while(*z && isspace((unsigned char)*z)) z++;
      continue;
    }
    if(temp==NULL){
      /* No-op: whitespace or comment */
      if(zNext) z = zNext;
      else break;
      continue;
    }
    sqlite3_finalize(temp);

    /* Get the text of this statement */
    int stmtLen = (zNext ? (int)(zNext-z) : (int)strlen(z));
    char *zStmt = (char*)malloc(stmtLen+1);
    memcpy(zStmt, z, stmtLen);
    zStmt[stmtLen] = 0;

    if(p->echoOn){
      oputs(p, zStmt);
      if(zStmt[stmtLen-1]!='\n') oputc(p, '\n');
    }
    if(p->traceOn && p->traceOut){
      fprintf(p->traceOut, "%s\n", zStmt);
    }

    /* Reset statistics for this statement */
    sqlite3_int64 prevChanges = sqlite3_total_changes64(p->db);

    rc = runOneSql(p, zStmt);

    if(p->printChanges){
      sqlite3_int64 nowChanges = sqlite3_total_changes64(p->db);
      fprintf(outFile(p), "changes: %lld   total_changes: %lld\n",
              (long long)(nowChanges - prevChanges),
              (long long)nowChanges);
    }

    free(zStmt);

    if(rc != SQLITE_OK){
      fprintf(stderr, "Error near line %d: %s\n",
              p->lineno, sqlite3_errmsg(p->db));
      p->nErr++;
      if(p->bail) return rc;
    }

    if(zNext) z = zNext;
    else break;

    /* Skip whitespace between statements */
    while(*z && isspace((unsigned char)*z)){
      if(*z=='\n') p->lineno++;
      z++;
    }
  }
  return rc;
}

