/* ============================================================
** Tokenize shell input into a argv array
** ============================================================ */
static int tokenize(const char *zLine, char ***pazArgs){
  int nArg=0, nAlloc=8;
  char **az = (char**)malloc(nAlloc*sizeof(char*));
  const char *z = zLine;

  while(*z && *z!='\n'){
    while(*z && isspace((unsigned char)*z) && *z!='\n') z++;
    if(!*z || *z=='\n') break;

    char buf[4096];
    int n=0;

    if(*z=='"' || *z=='\''){
      char q = *z++;
      while(*z && *z!=q){
        if(*z=='\\' && *(z+1)){
          z++;
          switch(*z){
            case 'n': buf[n++]='\n'; break;
            case 't': buf[n++]='\t'; break;
            case 'r': buf[n++]='\r'; break;
            default: buf[n++]=*z; break;
          }
        } else {
          buf[n++]=*z;
        }
        z++;
      }
      if(*z==q) z++;
    } else {
      while(*z && !isspace((unsigned char)*z) && *z!='\n'){
        buf[n++]=*z++;
      }
    }
    buf[n]=0;

    if(nArg>=nAlloc){
      nAlloc*=2;
      az=(char**)realloc(az, nAlloc*sizeof(char*));
    }
    az[nArg++]=strdup(buf);
  }
  *pazArgs = az;
  return nArg;
}

static void freeArgs(char **az, int n){
  int i;
  for(i=0;i<n;i++) free(az[i]);
  free(az);
}

