/* ============================================================
** Import CSV/text data
** ============================================================ */
typedef struct ImportCtx {
  const char *zFile;
  FILE *fp;
  char *z;
  int n;
  int sz;
  int eol;
  const char *zDataSep;
  int mode; /* 0=csv, 1=other */
  int nLine;
  int bHdr;
  int nSkip;
} ImportCtx;

static void importGrow(ImportCtx *c, int n){
  if(c->n+n+1 > c->sz){
    c->sz = c->sz*2+n+64;
    c->z = (char*)realloc(c->z, c->sz);
  }
}

/* Read one CSV field. Returns pointer to field, sets *pEOL=1 at line end */
static char *csvField(ImportCtx *c, int *pEOL){
  int ch;
  c->n = 0;
  *pEOL = 0;

  if(c->mode==0){ /* CSV */
    ch = fgetc(c->fp);
    if(ch==EOF){ *pEOL=1; return NULL; }

    if(ch=='"'){
      /* Quoted field */
      while(1){
        ch=fgetc(c->fp);
        if(ch==EOF){ break; }
        if(ch=='"'){
          int ch2=fgetc(c->fp);
          if(ch2=='"'){ importGrow(c,2); c->z[c->n++]='"'; }
          else {
            /* End of quoted field */
            if(ch2=='\n'||ch2==EOF) *pEOL=1;
            else if(ch2=='\r'){
              int ch3=fgetc(c->fp);
              if(ch3!='\n') ungetc(ch3,c->fp);
              *pEOL=1;
            }
            /* ch2 is ',' or EOL */
            break;
          }
        } else if(ch=='\n'){
          importGrow(c,2); c->z[c->n++]='\n';
        } else if(ch=='\r'){
          int ch2=fgetc(c->fp);
          if(ch2!='\n') ungetc(ch2,c->fp);
          importGrow(c,2); c->z[c->n++]='\n';
        } else {
          importGrow(c,2); c->z[c->n++]=(char)ch;
        }
      }
    } else {
      /* Unquoted field */
      while(ch!=',' && ch!='\n' && ch!='\r' && ch!=EOF){
        importGrow(c,2); c->z[c->n++]=(char)ch;
        ch=fgetc(c->fp);
      }
      if(ch=='\n') *pEOL=1;
      else if(ch=='\r'){
        *pEOL=1;
        int ch2=fgetc(c->fp);
        if(ch2!='\n') ungetc(ch2,c->fp);
      } else if(ch==EOF) *pEOL=1;
    }
  } else {
    /* Separated by zDataSep */
    int sepLen = (int)strlen(c->zDataSep);
    while(1){
      ch=fgetc(c->fp);
      if(ch==EOF){ *pEOL=1; break; }
      if(ch=='\n'){ *pEOL=1; c->nLine++; break; }
      if(ch=='\r'){
        int ch2=fgetc(c->fp);
        if(ch2!='\n') ungetc(ch2,c->fp);
        *pEOL=1; c->nLine++; break;
      }
      importGrow(c,2); c->z[c->n++]=(char)ch;
      /* Check for separator */
      if(c->n >= sepLen &&
         memcmp(c->z+c->n-sepLen, c->zDataSep, sepLen)==0){
        c->n -= sepLen;
        break;
      }
    }
  }

  importGrow(c, 1);
  c->z[c->n] = 0;
  return c->z;
}

/* ============================================================
** Clone a database
** ============================================================ */
static int doClone(ShellState *p, const char *zNewDb){
  /* Get list of tables */
  sqlite3 *pNew = NULL;
  int rc;
  char *zErr = NULL;

  rc = sqlite3_open_v2(zNewDb, &pNew,
       SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE, NULL);
  if(rc){
    fprintf(stderr, "Error: cannot open %s\n", zNewDb);
    return rc;
  }
  registerVersionFuncs(pNew);

  /* Get list of tables from old db */
  sqlite3_stmt *stmt = NULL;
  rc = sqlite3_prepare_v2(p->db,
    "SELECT name, sql FROM sqlite_master WHERE type='table' ORDER BY rowid",
    -1, &stmt, NULL);
  if(rc) { sqlite3_close(pNew); return rc; }

  while(sqlite3_step(stmt)==SQLITE_ROW){
    const char *name = (const char*)sqlite3_column_text(stmt, 0);
    const char *sql  = (const char*)sqlite3_column_text(stmt, 1);
    if(!name || !sql) continue;
    fprintf(outFile(p), "%s...", name);
    fflush(outFile(p));

    /* Create table in new db */
    sqlite3_exec(pNew, sql, NULL, NULL, &zErr);
    if(zErr){ sqlite3_free(zErr); zErr=NULL; }

    /* Copy data */
    char *zSel = sqlite3_mprintf("SELECT * FROM \"%w\"", name);
    sqlite3_stmt *sel=NULL;
    if(sqlite3_prepare_v2(p->db, zSel, -1, &sel, NULL)==SQLITE_OK){
      int nc = sqlite3_column_count(sel);
      while(sqlite3_step(sel)==SQLITE_ROW){
        /* Build INSERT */
        StrBuf sb; sb_init(&sb);
        sb_appendf(&sb, "INSERT INTO \"%s\" VALUES(", name);
        for(int i=0;i<nc;i++){
          if(i>0) sb_append(&sb, ",");
          int t=sqlite3_column_type(sel,i);
          if(t==SQLITE_NULL) sb_append(&sb,"NULL");
          else if(t==SQLITE_INTEGER){
            char buf[32];
            snprintf(buf,sizeof(buf),"%lld",(long long)sqlite3_column_int64(sel,i));
            sb_append(&sb,buf);
          } else if(t==SQLITE_FLOAT){
            char buf[64];
            snprintf(buf,sizeof(buf),"%.15g",sqlite3_column_double(sel,i));
            sb_append(&sb,buf);
          } else {
            const char *v=(const char*)sqlite3_column_text(sel,i);
            sb_append(&sb,"'");
            if(v) while(*v){
              if(*v=='\'') sb_append(&sb,"'");
              char cc[2]={*v,0};
              sb_append(&sb,cc);
              v++;
            }
            sb_append(&sb,"'");
          }
        }
        sb_append(&sb,")");
        sqlite3_exec(pNew, sb.z, NULL, NULL, &zErr);
        if(zErr){sqlite3_free(zErr);zErr=NULL;}
        sb_free(&sb);
      }
      sqlite3_finalize(sel);
    }
    sqlite3_free(zSel);
    fprintf(outFile(p), " done\n");
  }
  sqlite3_finalize(stmt);

  /* Copy indexes, views, triggers */
  rc = sqlite3_prepare_v2(p->db,
    "SELECT sql FROM sqlite_master WHERE type!='table' AND sql NOT NULL ORDER BY rowid",
    -1, &stmt, NULL);
  if(rc==SQLITE_OK){
    while(sqlite3_step(stmt)==SQLITE_ROW){
      const char *sql=(const char*)sqlite3_column_text(stmt,0);
      if(sql) sqlite3_exec(pNew, sql, NULL, NULL, &zErr);
      if(zErr){sqlite3_free(zErr);zErr=NULL;}
    }
    sqlite3_finalize(stmt);
  }

  sqlite3_close(pNew);
  return SQLITE_OK;
}

/* ============================================================
** .dump command
** ============================================================ */
static int doDump(ShellState *p, const char *zPattern){
  FILE *f = outFile(p);
  sqlite3_stmt *stmt = NULL;
  int rc;

  fprintf(f, "PRAGMA foreign_keys=OFF;\nBEGIN TRANSACTION;\n");

  const char *zQuery;
  if(zPattern && zPattern[0]){
    zQuery = "SELECT name, type, sql FROM sqlite_master WHERE sql NOT NULL"
             " AND name LIKE ? ORDER BY rowid";
  } else {
    zQuery = "SELECT name, type, sql FROM sqlite_master WHERE sql NOT NULL"
             " ORDER BY rowid";
  }

  rc = sqlite3_prepare_v2(p->db, zQuery, -1, &stmt, NULL);
  if(rc) return rc;
  if(zPattern && zPattern[0])
    sqlite3_bind_text(stmt, 1, zPattern, -1, SQLITE_STATIC);

  while(sqlite3_step(stmt)==SQLITE_ROW){
    const char *name = (const char*)sqlite3_column_text(stmt,0);
    const char *type = (const char*)sqlite3_column_text(stmt,1);
    const char *sql  = (const char*)sqlite3_column_text(stmt,2);

    if(!sql) continue;
    if(name && strcmp(name,"sqlite_sequence")==0) continue;

    /* Output CREATE statement */
    fprintf(f, "%s;\n", sql);

    /* If it's a table, output INSERT statements */
    if(type && strcmp(type,"table")==0){
      char *zSel = sqlite3_mprintf(
        "SELECT * FROM \"%w\"", name);
      sqlite3_stmt *sel=NULL;
      if(sqlite3_prepare_v2(p->db,zSel,-1,&sel,NULL)==SQLITE_OK){
        int nc = sqlite3_column_count(sel);
        while(sqlite3_step(sel)==SQLITE_ROW){
          fprintf(f, "INSERT INTO %s VALUES(", sql+12+1); /* after "CREATE TABLE " */
          /* Actually use name directly */
        }
        sqlite3_finalize(sel);
      }
      sqlite3_free(zSel);
      /* Re-do properly */
      zSel = sqlite3_mprintf("SELECT * FROM \"%w\"", name);
      if(sqlite3_prepare_v2(p->db,zSel,-1,&sel,NULL)==SQLITE_OK){
        nc = sqlite3_column_count(sel);
        while(sqlite3_step(sel)==SQLITE_ROW){
          fprintf(f, "INSERT INTO %s VALUES(", name);
          for(int i=0;i<nc;i++){
            if(i>0) fputc(',', f);
            int t=sqlite3_column_type(sel,i);
            if(t==SQLITE_NULL) fputs("NULL",f);
            else if(t==SQLITE_INTEGER)
              fprintf(f,"%lld",(long long)sqlite3_column_int64(sel,i));
            else if(t==SQLITE_FLOAT){
              char buf[64];
              snprintf(buf,sizeof(buf),"%.15g",sqlite3_column_double(sel,i));
              fputs(buf,f);
            } else if(t==SQLITE_BLOB){
              int nb=sqlite3_column_bytes(sel,i);
              const unsigned char *zb=(const unsigned char*)sqlite3_column_blob(sel,i);
              fputs("X'",f);
              for(int bi=0;bi<nb;bi++) fprintf(f,"%02X",zb[bi]);
              fputc('\'',f);
            } else {
              const char *v=(const char*)sqlite3_column_text(sel,i);
              fputc('\'',f);
              if(v) while(*v){if(*v=='\'')fputc('\'',f);fputc(*v,f);v++;}
              fputc('\'',f);
            }
          }
          fputs(");\n",f);
        }
        sqlite3_finalize(sel);
      }
      sqlite3_free(zSel);
    }
  }
  sqlite3_finalize(stmt);

  /* Check for sqlite_sequence */
  rc = sqlite3_prepare_v2(p->db,
    "SELECT name FROM sqlite_master WHERE name='sqlite_sequence'",
    -1, &stmt, NULL);
  if(rc==SQLITE_OK){
    if(sqlite3_step(stmt)==SQLITE_ROW){
      fprintf(f, "DELETE FROM sqlite_sequence;\n");
      sqlite3_stmt *ss=NULL;
      if(sqlite3_prepare_v2(p->db,"SELECT * FROM sqlite_sequence",-1,&ss,NULL)==SQLITE_OK){
        while(sqlite3_step(ss)==SQLITE_ROW){
          const char *sname=(const char*)sqlite3_column_text(ss,0);
          sqlite3_int64 sval=sqlite3_column_int64(ss,1);
          fprintf(f,"INSERT INTO sqlite_sequence VALUES('%s',%lld);\n",
                  sname?sname:"",(long long)sval);
        }
        sqlite3_finalize(ss);
      }
    }
    sqlite3_finalize(stmt);
  }

  fprintf(f, "COMMIT;\n");
  return SQLITE_OK;
}

