/* ============================================================
** SHA3 implementation (for .sha3sum)
** ============================================================ */
typedef unsigned long long u64;
typedef unsigned int u32;
typedef unsigned char u8;

typedef struct SHA3Context {
  union {
    u64 s[25];
    u8  x[1600];
  } u;
  int nRate;
  int nLoaded;
  int ixMask;
} SHA3Context;

static void SHA3Init(SHA3Context *p, int iSize){
  memset(p, 0, sizeof(*p));
  if(iSize==256) p->nRate=1088/8;
  else if(iSize==384) p->nRate=832/8;
  else p->nRate=576/8; /* 512 */
}

static const u64 KeccakF_RoundConstants[24] = {
  0x0000000000000001ULL, 0x0000000000008082ULL, 0x800000000000808aULL,
  0x8000000080008000ULL, 0x000000000000808bULL, 0x0000000080000001ULL,
  0x8000000080008081ULL, 0x8000000000008009ULL, 0x000000000000008aULL,
  0x0000000000000088ULL, 0x0000000080008009ULL, 0x000000008000000aULL,
  0x000000008000808bULL, 0x800000000000008bULL, 0x8000000000008089ULL,
  0x8000000000008003ULL, 0x8000000000008002ULL, 0x8000000000000080ULL,
  0x000000000000800aULL, 0x800000008000000aULL, 0x8000000080008081ULL,
  0x8000000000008080ULL, 0x0000000080000001ULL, 0x8000000080008008ULL
};

static void KeccakF1600(u64 *a){
  int i;
  u64 B[5][5], C[5], D[5];
  for(int round=0; round<24; round++){
    for(i=0;i<5;i++) C[i]=a[i]^a[i+5]^a[i+10]^a[i+15]^a[i+20];
    for(i=0;i<5;i++){
      D[i]=C[(i+4)%5] ^ (C[(i+1)%5]<<1 | C[(i+1)%5]>>63);
      for(int j=0;j<25;j+=5) a[i+j]^=D[i];
    }
    /* rho and pi */
    u64 last=a[1];
    static const int piln[24]={
      10,7,11,17,18,3,5,16,8,21,24,4,15,23,19,13,12,2,20,14,22,9,6,1};
    static const int rotc[24]={
      1,3,6,10,15,21,28,36,45,55,2,14,27,41,56,8,25,43,62,18,39,61,20,44};
    for(i=0;i<24;i++){
      int j=piln[i];
      u64 temp=a[j];
      int r=rotc[i];
      a[j]=(last<<r)|(last>>(64-r));
      last=temp;
    }
    /* chi */
    for(int j=0;j<25;j+=5){
      for(i=0;i<5;i++) B[0][i]=a[j+i];
      for(i=0;i<5;i++) a[j+i]=B[0][i]^((~B[0][(i+1)%5])&B[0][(i+2)%5]);
    }
    /* iota */
    a[0]^=KeccakF_RoundConstants[round];
  }
}

static void SHA3Update(SHA3Context *p, const u8 *data, int n){
  int len=n;
  while(len>0){
    int i=p->nLoaded;
    if(i==0 && len>=p->nRate){
      /* Process directly */
      for(int j=0;j<p->nRate/8;j++){
        p->u.s[j] ^= ((u64*)data)[j];
      }
      KeccakF1600(p->u.s);
      data+=p->nRate; len-=p->nRate;
    } else {
      int need=p->nRate-i;
      int take=len<need?len:need;
      for(int j=0;j<take;j++) p->u.x[i+j]^=data[j];
      p->nLoaded+=take;
      data+=take; len-=take;
      if(p->nLoaded==p->nRate){
        KeccakF1600(p->u.s);
        p->nLoaded=0;
      }
    }
  }
}

static u8 *SHA3Final(SHA3Context *p){
  p->u.x[p->nLoaded]^=0x06;
  p->u.x[p->nRate-1]^=0x80;
  KeccakF1600(p->u.s);
  p->ixMask=0;
  return p->u.x;
}

