static void showHelp(ShellState *p, const char *zPattern){
  FILE *f = outFile(p);
  const char *z = zHelpText;
  while(*z){
    const char *eol = strchr(z, '\n');
    int len = eol ? (int)(eol-z) : (int)strlen(z);
    if(!zPattern || zPattern[0]==0 || strstr(z, zPattern)!=NULL){
      fwrite(z, 1, len, f);
      fputc('\n', f);
    }
    if(!eol) break;
    z = eol+1;
  }
}

/* ============================================================
** .databases command
** ============================================================ */
static void doDatabases(ShellState *p){
  FILE *f = outFile(p);
  sqlite3_stmt *stmt=NULL;
  if(sqlite3_prepare_v2(p->db,
     "PRAGMA database_list", -1, &stmt, NULL)==SQLITE_OK){
    while(sqlite3_step(stmt)==SQLITE_ROW){
      const char *name=(const char*)sqlite3_column_text(stmt,1);
      const char *file=(const char*)sqlite3_column_text(stmt,2);
      /* Check if read-only */
      int ro = sqlite3_db_readonly(p->db, name);
      fprintf(f, "%s: \"%s\" %s\n",
              name?name:"",
              file?file:"",
              ro>0?"r/o":"r/w");
    }
    sqlite3_finalize(stmt);
  }
}

