    }
    char buf[4096];
    StrBuf sb; sb_init(&sb);
    while(fgets(buf,sizeof(buf),fp)) sb_append(&sb,buf);
    fclose(fp);
    /* Process contents */
    const char *z=sb.z;
    while(z && *z){
      /* Skip whitespace */
      while(*z && isspace((unsigned char)*z) && *z!='\n') z++;
      if(!*z) break;
      if(*z=='.'){
        /* Find end of line */
        const char *eol=strchr(z,'\n');
        char linebuf[4096];
        int ll=eol?(int)(eol-z):(int)strlen(z);
        if(ll>4095)ll=4095;
        memcpy(linebuf,z,ll); linebuf[ll]=0;
        processCmd(p, linebuf);
        z=eol?eol+1:z+strlen(z);
      } else {
        /* SQL until ';' or next dot command */
        const char *start=z;
        /* Collect until end of SQL (handle multiline) */
        StrBuf sql; sb_init(&sql);
        while(*z){
          if(*z=='.' && (z==start || *(z-1)=='\n')){break;}
          char c[2]={*z,0}; sb_append(&sql,c);
          z++;
        }
        if(sql.n>0 && p->db){
