  if(strcmp(cmd,"import")==0){
    /* .import [--csv|--ascii] [--skip N] FILE TABLE */
    if(nArg<3){freeArgs(az,nArg);return 0;}
    const char *zFile=NULL, *zTable=NULL;
    int skipRows=0;
    int iMode=p->mode;
    for(int i=1;i<nArg;i++){
      if(strcmp(az[i],"--csv")==0) iMode=MODE_Csv;
      else if(strcmp(az[i],"--ascii")==0) iMode=MODE_Ascii;
      else if(strcmp(az[i],"--skip")==0 && i+1<nArg){
        skipRows=atoi(az[++i]);
      } else if(!zFile) zFile=az[i];
      else zTable=az[i];
    }
    if(!zFile||!zTable){freeArgs(az,nArg);return 0;}

    FILE *fp=fopen(zFile,"r");
    if(!fp){
      fprintf(stderr,"Error: cannot open \"%s\"\n",zFile);
      p->nErr++;
      freeArgs(az,nArg); return 0;
    }

    /* Check if table exists */
    int tableExists=0;
    {
      char *zQ=sqlite3_mprintf(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='%q'",zTable);
      sqlite3_stmt *cs=NULL;
      if(sqlite3_prepare_v2(p->db,zQ,-1,&cs,NULL)==SQLITE_OK){
        if(sqlite3_step(cs)==SQLITE_ROW) tableExists=1;
        sqlite3_finalize(cs);
      }
      sqlite3_free(zQ);
    }

    ImportCtx ic;
    memset(&ic,0,sizeof(ic));
    ic.fp=fp;
    ic.zFile=zFile;
    ic.nLine=1;
    if(iMode==MODE_Csv){
      ic.mode=0; ic.zDataSep=",";
    } else {
      ic.mode=1; ic.zDataSep=p->colSep;
    }

    /* Skip N rows */
    for(int s=0;s<skipRows;s++){
      char buf[4096];
      fgets(buf,sizeof(buf),fp);
    }

    /* Read first row for headers if table doesn't exist */
    char **colNames=NULL; int nCols=0;
    if(!tableExists){
      /* First row = column names */
      int eol=0;
      char **vals=NULL; int nv=0, nva=0;
      while(!eol){
        char *fld=csvField(&ic,&eol);
        if(fld==NULL && eol) break;
        if(nv>=nva){nva=nva*2+8;vals=(char**)realloc(vals,nva*sizeof(char*));}
        vals[nv++]=fld?strdup(fld):strdup("");
      }
      nCols=nv;
      colNames=(char**)malloc(nCols*sizeof(char*));
      for(int i=0;i<nCols;i++) colNames[i]=vals[i];
      free(vals);

      /* Create table */
      StrBuf sb; sb_init(&sb);
      sb_appendf(&sb,"CREATE TABLE \"%s\"(\n",zTable);
      for(int i=0;i<nCols;i++){
        if(i>0) sb_append(&sb,",\n");
        sb_appendf(&sb,"\"%s\" ANY",colNames[i]);
      }
      sb_append(&sb,"\n)");
      char *zErr=NULL;
      sqlite3_exec(p->db,sb.z,NULL,NULL,&zErr);
      if(zErr){
        fprintf(stderr,"Error creating table: %s\n",zErr);
        sqlite3_free(zErr);
      }
      sb_free(&sb);
    } else {
      /* Get column count from table */
      char *zQ=sqlite3_mprintf("SELECT * FROM \"%w\" LIMIT 0",zTable);
      sqlite3_stmt *cs=NULL;
      if(sqlite3_prepare_v2(p->db,zQ,-1,&cs,NULL)==SQLITE_OK){
        nCols=sqlite3_column_count(cs);
        colNames=(char**)malloc(nCols*sizeof(char*));
        for(int i=0;i<nCols;i++){
          const char *cn=sqlite3_column_name(cs,i);
          colNames[i]=cn?strdup(cn):strdup("");
        }
        sqlite3_finalize(cs);
      }
      sqlite3_free(zQ);
    }

    /* Build INSERT statement */
    StrBuf insQ; sb_init(&insQ);
    sb_appendf(&insQ,"INSERT INTO \"%s\" VALUES(",zTable);
    for(int i=0;i<nCols;i++){
      if(i>0) sb_append(&insQ,",");
      sb_appendf(&insQ,"?%d",i+1);
    }
    sb_append(&insQ,")");

    sqlite3_stmt *ins=NULL;
    if(sqlite3_prepare_v2(p->db,insQ.z,-1,&ins,NULL)!=SQLITE_OK){
      fprintf(stderr,"Error preparing insert\n");
    }
    sb_free(&insQ);

    /* Begin transaction */
    sqlite3_exec(p->db,"BEGIN",NULL,NULL,NULL);

    /* Read data rows */
    int nImported=0;
    while(ins && !feof(fp)){
      char **vals=NULL; int nv=0, nva=0;
      int eol=0;
      while(!eol){
        char *fld=csvField(&ic,&eol);
        if(fld==NULL && eol && nv==0) goto done_import;
        if(nv>=nva){nva=nva*2+8;vals=(char**)realloc(vals,nva*sizeof(char*));}
        vals[nv++]=fld?strdup(fld):strdup("");
      }
      if(nv==0 || (nv==1 && vals[0][0]==0)){
        for(int i=0;i<nv;i++) free(vals[i]);
        free(vals);
        continue;
      }
      sqlite3_reset(ins);
      for(int i=0;i<nCols && i<nv;i++){
        sqlite3_bind_text(ins,i+1,vals[i],-1,SQLITE_TRANSIENT);
      }
      for(int i=nv;i<nCols;i++) sqlite3_bind_null(ins,i+1);
      sqlite3_step(ins);
      for(int i=0;i<nv;i++) free(vals[i]);
      free(vals);
      nImported++;
    }
done_import:
    sqlite3_exec(p->db,"COMMIT",NULL,NULL,NULL);
    if(ins) sqlite3_finalize(ins);
    if(colNames){
      for(int i=0;i<nCols;i++) free(colNames[i]);
      free(colNames);
    }
    free(ic.z);
    fclose(fp);
    freeArgs(az,nArg); return 0;
