  if(strcmp(cmd,"import")==0){
    /* .import [--csv|--ascii] [--skip N] FILE TABLE */
    if(nArg<3){freeArgs(az,nArg);return 0;}
    const char *zFile=NULL, *zTable=NULL;
    int skipRows=0;
