    ImportCtx ic;
    memset(&ic,0,sizeof(ic));
    ic.fp=fp;
    ic.zFile=zFile;
    ic.nLine=1;
    if(iMode==MODE_Csv){
      ic.mode=0; ic.zDataSep=",";
    } else {
      ic.mode=1; ic.zDataSep=p->colSep;
    }

    /* Skip N rows */
    for(int s=0;s<skipRows;s++){
      char buf[4096];
      fgets(buf,sizeof(buf),fp);
    }

    /* Read first row for headers if table doesn't exist */
    char **colNames=NULL; int nCols=0;
    if(!tableExists){
      /* First row = column names */
      int eol=0;
      char **vals=NULL; int nv=0, nva=0;
      while(!eol){
        char *fld=csvField(&ic,&eol);
        if(fld==NULL && eol) break;
        if(nv>=nva){nva=nva*2+8;vals=(char**)realloc(vals,nva*sizeof(char*));}
        vals[nv++]=fld?strdup(fld):strdup("");
      }
      nCols=nv;
      colNames=(char**)malloc(nCols*sizeof(char*));
      for(int i=0;i<nCols;i++) colNames[i]=vals[i];
      free(vals);

      /* Create table */
      StrBuf sb; sb_init(&sb);
      sb_appendf(&sb,"CREATE TABLE \"%s\"(\n",zTable);
      for(int i=0;i<nCols;i++){
        if(i>0) sb_append(&sb,",\n");
        sb_appendf(&sb,"\"%s\" ANY",colNames[i]);
      }
      sb_append(&sb,"\n)");
      char *zErr=NULL;
      sqlite3_exec(p->db,sb.z,NULL,NULL,&zErr);
      if(zErr){
        fprintf(stderr,"Error creating table: %s\n",zErr);
        sqlite3_free(zErr);
      }
      sb_free(&sb);
    } else {
      /* Get column count from table */
      char *zQ=sqlite3_mprintf("SELECT * FROM \"%w\" LIMIT 0",zTable);
      sqlite3_stmt *cs=NULL;
      if(sqlite3_prepare_v2(p->db,zQ,-1,&cs,NULL)==SQLITE_OK){
        nCols=sqlite3_column_count(cs);
        colNames=(char**)malloc(nCols*sizeof(char*));
        for(int i=0;i<nCols;i++){
          const char *cn=sqlite3_column_name(cs,i);
          colNames[i]=cn?strdup(cn):strdup("");
        }
        sqlite3_finalize(cs);
