  processInput(&state, stdin);

cleanup:
  if(state.db) sqlite3_close(state.db);
  if(state.out != stdout) fclose(state.out);
  if(state.pLog && state.pLog!=stdout && state.pLog!=stderr) fclose(state.pLog);
