  while(z && *z){
    const char *zNext = NULL;
    sqlite3_stmt *temp = NULL;
    int rc2;

    /* Skip whitespace */
    while(*z && isspace((unsigned char)*z)){
      if(*z=='\\n') p->lineno++;
      z++;
    }
    if(!*z) break;

    /* Find the end of this statement */
    rc2 = sqlite3_prepare_v2(p->db, z, -1, &temp, &zNext);
    if(rc2 != SQLITE_OK){
      const char *zErrMsg = sqlite3_errmsg(p->db);
      fprintf(stderr, "Parse error near line %d: %s\\n",
              p->lineno, zErrMsg);
      /* Find error token and show pointer */
      {
        const char *tok = NULL;
        int tokLen = 0;
        const char *ep = strstr(zErrMsg, "near \\"");
        if(ep){
          ep += 6;
          const char *eq = strchr(ep, '"');
          if(eq){ tok=ep; tokLen=(int)(eq-ep); }
        }
        /* Find the problematic line */
