            /* Find the line containing the error */
            const char *lineEnd = strchr(cp, '\\n');
            int lineLen = lineEnd ? (int)(lineEnd-cp) : (int)strlen(cp);
            char lineBuf[1024];
            if(lineLen >= 1023) lineLen=1022;
            memcpy(lineBuf, cp, lineLen); lineBuf[lineLen]=0;
            /* Remove trailing whitespace */
            while(lineLen>0 && (lineBuf[lineLen-1]=='\\n'||lineBuf[lineLen-1]=='\\r'||lineBuf[lineLen-1]==';')) 
              lineBuf[--lineLen]=0;
            fprintf(stderr, "  %s\\n", lineBuf);
