    /* Get the text of this statement */
    int stmtLen = (zNext ? (int)(zNext-z) : (int)strlen(z));
    char *zStmt = (char*)malloc(stmtLen+1);
    memcpy(zStmt, z, stmtLen);
    zStmt[stmtLen] = 0;
    /* Trim trailing whitespace from stmt */
    int sl = stmtLen;
    while(sl>0 && isspace((unsigned char)zStmt[sl-1])) sl--;
