new = '''/* Return alignment for a column:
** 0 = left, 1 = right, 2 = center (for numeric headers) */
static int getAlign(ShellState *p, int col, ColBuf *c, int isHeader){
  int preset = (col < p->nWidth) ? p->colWidth[col] : 0;
  int t = c->aType[col];
  int isNumeric = (t==SQLITE_INTEGER || t==SQLITE_FLOAT);
  if(isHeader && isNumeric) return 2;  /* Center for numeric headers */
  if(isHeader) return 0;               /* Left for text headers */
  if(preset < 0) return 1;             /* Preset negative = right */
  return isNumeric ? 1 : 0;            /* Right for numeric data, left for text */
}
static int isRightAlign(ShellState *p, int col, ColBuf *c, int isHeader){
  return getAlign(p, col, c, isHeader) == 1;
}'''

